quests[780] = { id = 780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battleboars", description = "The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war.\n\nGo and slay the vile creatures and bring back some snouts and flanks so that we can make stew for our young.", sourceObjective = "Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.", progress = "The aggression of the Battleboars is increasing. Have you sent them a clear message and brought back some snouts and flanks yet?", completion = "Most excellent. These ingredients will make a fine stew and the loss of those boars should be a fair lesson to those vile Bristlebacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[781] = { id = 781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Camp Narache", description = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!", sourceObjective = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.", progress = "You have a look of concern about you, {name}. What news do you bring?", completion = "This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many {race}, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[782] = { id = 782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Alliances", description = "From the Horde's alliance with the dragon Deathwing during the Second War, we know that two of his lieutenants, Blacklash and Hematus, were imprisoned within Lethlor Ravine far to the east. We must silence our depraved allies of old to restore honor to the Horde!\n\nWe hired Tho'grun and his band of ogre mercenaries to help us obtain the Sign of the Earth, a key needed to unlock the drakes' prison. Tho'grun betrayed us though, overwhelming us and taking it for himself. Go to Camp Boff and take it back!", sourceObjective = "Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.", progress = "Tho'grun's betrayal... is there any wonder why the ogres are part of the Horde no longer? I will be glad to see him dead, and the Sign of the Earth returned.\n\nIf you've not dispatched him yet, then waste no time going to Camp Boff.  It is to the southeast of Kargath.", completion = "With Tho'grun dead, his corpse picked clean by the desert winds and scavenging buzzards, the ogres will be put into disarray. Though a small victory, this will lead to a much larger one\n\nThe Sign of the Earth is now in our possession, and we can open the black drakes' prison in Lethlor.  We shall free them from endless imprisonment, albeit to their doom!", sourceObjectiveStatus = "unverified-source-field" }
quests[783] = { id = 783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Threat Within", description = "I hope you strapped your belt on tight, young {class}, because there is work to do here in Northshire.\n\nAnd I don't mean farming.\n\nThe Stormwind guards are hard pressed to keep the peace here, with so many of us in distant lands and so many threats pressing close.  And so we're enlisting the aid of anyone willing to defend their home.  And their alliance.\n\nIf you're here to answer the call, then speak with my superior, Marshal McBride.  He's inside the abbey behind me.", sourceObjective = "Speak with Marshal McBride.", completion = "Ah, good.  Another volunteer.  We're getting a lot of you these days.\n\nI hope it's enough.\n\nThe {race} lands are threatened from without, and so many of our forces have been marshaled abroad.  This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.\n\nIt is a many-fronted battle we wage, {name}.  Gird yourself for a long campaign.", sourceObjectiveStatus = "unverified-source-field" }
quests[784] = { id = 784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquish the Betrayers", description = "Led by Admiral Proudmoore, the humans of Kul Tiras encroached on Durotar, violating the Warchief's pact made with Jaina Proudmoore in order to defeat Archimonde years ago.\n\nThe human aggression was repelled and Tiragarde Keep fell. But recently, the Admiral's reserves, led by Lieutenant Benedict, have retaken the keep and once again pose a threat to our homeland. These humans show no respect for diplomacy.\n\nProve your honor and travel south to Tiragarde Keep to eliminate the human invaders.", sourceObjective = "Kill 10 Kul Tiras Sailors, 8 Kul Tiras Marines and Lieutenant Benedict and return to Gar'Thok in Razor Hill.", progress = "You have your orders, {name}. The safety of Durotar is in question. Complete the task before you or hang your head in shame.\n\nShow your honor and defeat the humans of Tiragarde Keep.", completion = "Word of your bravery travels fast, {class}. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[785] = { id = 785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strategic Alliance", description = "Thrall is a most wise and noble leader. His tenacity on the battlefield is matched only by his diplomatic tact.\n\nThe Darkspear Trolls have proven to be invaluable allies to orckind. Out of loyalty and honor we have sworn a pact of protection with them.\n\nThe Warchief has sent orders to make sure our Darkspear friends in Sen'jin Village are not under any direct threat. One of their most trusted scouts, Lar Prowltusk is keeping a close watch on their western flank.\n\nSeek out Lar and assist as needed.", sourceObjective = "Seek out Lar Prowltusk on the western flank of Sen'jin Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[786] = { id = 786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thwarting Kolkar Aggression", description = "Lower your voice, {class}. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag.\n\nLast night while they were raiding, I snuck into their village and discovered that the dirty beasts have a three-tiered attack planned on the trolls and orcs of Durotar.\n\nWe mustn't let their invasion come to fruition. Perhaps you can muster the might needed to infiltrate Kolkar Crag and destroy their attack plans.\n\nLast I saw, they had divided them up amongst three of their leaders.", sourceObjective = "Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.", progress = "The centaurs have proven to be a consistent nuisance to the Horde. Their intentions to lay siege to our homeland cannot be tolerated.", completion = "The Horde would surely prevail if the Kolkar centaurs were to attack. But by preventing such an attack, we have spared our mighty warriors unnecessary bloodshed.\n\nAnd as sure as there is sand in the Tanaris desert, we know that there will be blood spilled before these trying times are through.\n\nYou have served your people well, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[787] = { id = 787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Horde", description = "Throm'ka, {class}. I am Eitrigg, charged by Thrall to oversee the training of recruits.\n\nThe Horde has changed from what it once was. There was a time where I left the Horde, disillusioned by the growing influence of the power-hungry pawns of the Burning Legion. During my exile, I was taken prisoner by a group of humans, but was rescued by the Warchief. Hearing his vision of the Horde free of demonic influence, guided by the shamans, I returned.\n\nGornek will have further instructions for you.", sourceObjective = "Report to Gornek in the Den.", sourceObjectiveStatus = "unverified-source-field" }
quests[788] = { id = 788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Teeth", description = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.\n\nI believe you would find a good match with the mottled boars you'll find to the north of here.", sourceObjective = "Kill 8 Mottled Boars then return to Gornek at the Den.", progress = "I hope you haven't returned to try and convince me that you have completed your task, {name}? No, of course not. I would think better of you.", completion = "Hmmm, not bad, {name}. But don't let it get to your head...you'll fight tougher than boars in your career.\n\nNonetheless, you've proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you'll need some extra protection.", sourceObjectiveStatus = "unverified-source-field" }
quests[789] = { id = 789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sting of the Scorpid", description = "Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here. Bring me eight of their tails as proof of your prowess in battle.\n\nThe antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...\n\nBut I'm sure you won't be needing any of that, will you?", sourceObjective = "Get 8 Scorpid Worker Tails for Gornek in the Den.", progress = "The carapace of a scorpid isn't so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.", completion = "There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.\n\nI have no more to teach you, {name}. You have done well, and I will watch your progress with interest.", sourceObjectiveStatus = "unverified-source-field" }
quests[790] = { id = 790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkoth", description = "{class}! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.\n\nI wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.", sourceObjective = "Kill Sarkoth and bring his claw back to Hana'zua.", progress = "Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right.\n\nAt least I wish to die knowing that my last enemy in life lays dead.", completion = "My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life's accomplishments fills me with anger.", sourceObjectiveStatus = "unverified-source-field" }
quests[791] = { id = 791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carry Your Weight", description = "Age has rendered me useless in battle. Now I make myself useful in other ways.\n\nFrom this vantage point I watch for invaders. As our strength here grows, I find myself blowing the signal horn less and less.\n\nTo pass the time I fashion goods to help younger, more able warriors defend our homeland.\n\nFor you, I can fashion you a bag for your belongings. If such an item would be of use to you, bring me some canvas, a material common to the humans and centaurs.", sourceObjective = "Furl Scornbrow in the Razor Hill watchtower wants 8 Canvas Scraps.", progress = "I fought proudly alongside the Warchief when these lands were pioneered. The scars of battle mark my skin.\n\nThe honor of the Horde has been upheld with the help of my axe and battlecry during the defeat of Archimonde, when the unholy alliance was made with the humans and elves, wrought from necessity.\n\nBut my position as watchman and provider has given me a new sense of worth.", completion = "Most excellent, {name}. Any good {class} will surely find a use for this bag on the battlefield.\n\nI salute your vigor and willingness to die in the name of the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[792] = { id = 792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Familiars", description = "I trust the Valley of Trials will teach you much, young {class}.\n\nI was sent to the Valley to guide you, but I have discovered a growing taint here...\n\nA group that calls itself the Burning Blade has a coven here in the Valley of Trials.  They are skulking in a cave to the northeast, and their Vile Familiars have spilled from its mouth to cause havoc.\n\nAs your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.", sourceObjective = "Kill 8 Vile Familiars.\n\nReturn to Zureetha Fargaze outside the Den.", progress = "To prove yourself against the Burning Blade, you must first defeat its Vile Familiars.  Return to me when you have done this.", completion = "You have done well, {name}.\n\nAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.", sourceObjectiveStatus = "unverified-source-field" }
quests[793] = { id = 793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Alliances", description = "The Seal of the Earth is held by three runestones, held in the Pillars of Diamond, Opal, and Amethyst in Lethlor Ravine. Using the Sign of the Earth, you will be able to remove the runestones and unlock the Seal of the Earth.\n\nBe wary though, {name}, the black drakes Blacklash and Hematus are not to be trifled with. See them dead and return their bindings to me.\n\nTo reach the ravine, travel to the far eastern part of the Badlands.  Be careful though, for the ravine is home to countless drakes.", sourceObjective = "Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.\n\nPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.\n\nSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn.", progress = "There are few enemies more deadly than dragonkind, and there were few dragons that fought as ferociously as Blacklash and Hematus.", completion = "The black dragonflight continues to ally with the renegade Blackrock orcs, and both must be brought into line, or removed. With Blacklash and Hematus dead, we can turn our attentions westwards, towards Blackrock Spire.", sourceObjectiveStatus = "unverified-source-field" }
quests[794] = { id = 794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Blade Medallion", description = "Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic.\n\nIt is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven.\n\nBut be wary, for the medallion may be possessed by an agent of the Burning Blade, and if so then the agent's power would be greater than the familiars you have already encountered.\n\nGo, {name}.  You will find the coven in a cave, to the north and west.", sourceObjective = "Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den.", progress = "Is your task complete, {name}?  Do you have the Burning Blade Medallion?", completion = "You retrieved it!  Well done!\n\nYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials.  But I fear they have further aims in our land.\n\nWe have not seen the end of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[795] = { id = 795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seal of the Earth", progress = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", completion = "As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken." }
quests[804] = { id = 804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarkoth", description = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!\n\nBut it remains that I cannot make the trek back to the Den unassisted. Please, {name}, return to the Den and tell Gornek of my situation. Perhaps he can help me.", sourceObjective = "Bring the news of Hana'zua's plight to Gornek at the Den.", completion = "From your description of the beast, I believe you must be speaking of Sarkoth! It is no wonder that Hana'zua was overtaken by it. Aid will be dispatched to him immediately, trouble yourself no more with Hana'zua's plight.\n\nHowever, I must say, I am most impressed to hear that you brought Sarkoth to death. It is a feat to be proud of, {name}. And that you would fight for a stranger's honor, while other tasks occupied your time, your own honor is heightened.", sourceObjectiveStatus = "unverified-source-field" }
quests[805] = { id = 805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Sen'jin Village", description = "Your trials against the Burning Blade are finished... here in the Valley.  But I want you to report your findings.\n\nGo to the troll village of Sen'jin and seek out Master Gadrin.  Sen'jin Village is east out of the valley, then right at the fork.\n\nTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials.  Discover from him if they have yet reached Sen'jin.\n\nGo, {name}, and be swift.  I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...", sourceObjective = "Speak with Master Gadrin in Sen'jin Village.", completion = "Hm... your report comes at a bad time.  The Burning Blade is not seen here in Sen'jin, but their evil has taken seed off the coast, on the Echo Isles.\n\nThe orcs are friends of the Darkspear Trolls.  Honorable friends.  We want to help the orcs, but... we need help too.", sourceObjectiveStatus = "unverified-source-field" }
quests[806] = { id = 806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Storms", description = "We cannot allow the Burning Blade a foothold in Durotar!  We must destroy them before their evil festers!\n\nI have undergone my own investigations and found that a Burning Blade warlock, the goblin Fizzle Darkstorm, has camped within Thunder Ridge to the northwest.  There he and his cultist minions spread chaos.\n\nFind and defeat Fizzle, and bring me his dead claw!", sourceObjective = "Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.", progress = "Did you find Fizzle, {name}?  He, and rest of the Burning Blade, must be scoured from our lands!", completion = "Aha!  You got him!\n\nYou do your clan proud, {name}.  And because of you, Durotar is free of one more agent of evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[808] = { id = 808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minshina's Skull", description = "I hear the voice of my brother, Minshina, calling to me in my dreams.\n\nHe was taken by Zalazane, the warlock on the Echo Isles to the east. And he is dead.\n\nBut death is not freedom for my brother. Minshina's spirit was trapped within his own skull by Zalazane's magics. In my dreams I see it with other skulls, in a circle of power on the largest Echo Isle. As long as it remains there my brother's soul is doomed.\n\nPlease, {name}. Find the circle and retrieve Minshina's skull. Bring it to me.\n\nFree him!", sourceObjective = "Retrieve Minshina's skull from the circle of power on the Echo Isles.\n\nBring it to Master Gadrin in Sen'jin Village.", progress = "Do you have my brother's skull, {name}?  Is he finally free?", completion = "Thank you, {name}.  You have saved Minshina.  You have saved my brother's spirit from slavery!", sourceObjectiveStatus = "unverified-source-field" }
quests[809] = { id = 809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ak'Zeloth", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed!\n\nGo to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further.", sourceObjective = "Speak with Ak'Zeloth in the Barrens.", completion = "Neeru wants the Demon Seed destroyed, does he?  Strange...\n\nVery well.  If he wishes the seed gone, then I will tell you how to remove it.", sourceObjectiveStatus = "unverified-source-field" }
quests[812] = { id = 812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need for a Cure", description = "{name}... your timing is perfect. I just hope I can compliment your haste as well.\n\nI was careless while fighting a few of the venomtails nearby, and one of them stung me deeply. I can feel its poison weakening me even as we speak. At this rate, I got maybe an hour left to live. But I'll need your help if I'm to do so...\n\nKor'ghan in Orgrimmar knows how to make the antidote. Find him... and hurry, {name}. I won't be able to last much longer. He should be in the Cleft of Shadow.", sourceObjective = "Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar.", progress = "I'm almost glad I can't return to Sen'jin as I am now. My weakness and stupidity would surely be mocked.", completion = "{name}, you've saved my life. Thank you.\n\nPlease take this; I hope it can at least help you in your travels, if not bring you some coin. From what you say, I won't be usin' it anytime soon. Kor'ghan is gonna march me through more of his rituals until I prove myself. More killin' boars, more gatherin' scorpid tails...", sourceObjectiveStatus = "unverified-source-field" }
quests[813] = { id = 813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Antidote", description = "Venomtails are some of the deadliest scorpids in Durotar. It was unwise for Rhinag to hunt them without having some of the antidote with him, but right now, chastising is the last thing he needs.\n\nBring me a few venomtail poison sacs from any of the venomtails near the entrance of Orgrimmar and I'll make an antidote for him.\n\nMake haste, {name}. One of our own needs your help.", sourceObjective = "Bring 4 Venomtail Poison Sacs to Kor'ghan in Orgrimmar.", progress = "Remember, no matter what creature you hunt, you would do well to study it and understand its behavior. That knowledge could save your life.", completion = "Here is the antidote, {name}. Take it to Rhinag as soon as you can, and be cautious.", sourceObjectiveStatus = "unverified-source-field" }
quests[815] = { id = 815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break a Few Eggs", description = "Bah! I almost forgot I need to get breakfast ready.\n\n{name}, get yourself movin' and get me some taillasher eggs. I'll need at least three of them if I'm going to have enough for tomorrow's meal.\n\nThe Bloodtalon taillashers can be fierce, and protect their eggs to the death more often than not. They sometimes bury their eggs too deep in the earth to uncover safely, but if you head to the Echo Isles to the southeast of Sen'jin Village, you can usually find them all over those islands.", sourceObjective = "Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.", progress = "Breakfast, lunch, dinner! Who cares which meal it is? It still has to be cooked by someone--namely me!", completion = "You might be weak, but at least you're not clumsy, {name}.\n\nHere, take this and get outta my way. I've got cooking to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[816] = { id = 816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost But Not Forgotten", description = "{name}, please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River. I fear the worst.\n\nAs strong as he was, his stubborn pride has always drawn him into trouble. I warned him that the crocolisks were powerful and vicious. He grew angry and stormed off.\n\nIf you can't find him, at least bring me a sign of his fate... even if you have to open up the stomach of every crocolisk along the Southfury's banks.", sourceObjective = "Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill.", progress = "I pray that Kron will return to me, but I'm almost certain I know his fate already.", completion = "Oh, my son... my beautiful son.\n\nUncertain of my son's fate, I have tormented myself since he left. Now that I know what's happened, perhaps I can finally begin to mourn.\n\nThank you, {name}. Please take this. I was going to give it to Kron as a gift when he returned successful. Now that I know he is dead, I cannot bear to look at it.", sourceObjectiveStatus = "unverified-source-field" }
quests[817] = { id = 817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Practical Prey", description = "Many of the hides we use come from Durotar tigers, {name}. Blankets, armor, tents: there are a great many reasons we hunt the beasts, and many reasons we let them thrive at the same time.\n\nThe time has come for us to cull the flock, so to speak. Our numbers grow, and our needs are beginning to overwhelm our stocks. I need more hides if I'm to prepare suitable goods for our people.\n\nBring me 4 Durotar tiger furs, and I shall reward you. You can find them on the islands south of here.", sourceObjective = "Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village.", progress = "I remember my first tiger hunt, {name}. I chose to hunt on the largest of the Echo Isles, and I sat perfectly still in the shadows of its foliage for almost a full day... watching... waiting.\n\nMy muscles were taut, and I was ready to strike. It was one of my greatest victories when that tiger finally took the bait.", completion = "I am pleased, {name}. Because of your help, our people will be protected, and not go cold as the seasons change.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[818] = { id = 818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Solvent Spirit", description = "Although my eyes fail me, I still can see clearly enough. More often I must rely on my alchemical skills to aid me in magics that once came easily. But I refuse to take on an apprentice--no troll or orc worthy enough has ever come forward.\n\nAre you worthy? Yes, of course you are... of course you think you are.\n\nI need a few things. Will you get them for me?\n\nI need intact makrura eyes, and vials of crawler mucus. You can find them on any makrura or crawler in Durotar. We shall speak again soon.", sourceObjective = "Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village.", progress = "Time is the true test of your strength and will. Lose patience or give in to weakness, and your true self will be shown.", completion = "Well done, young one... well done indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[819] = { id = 819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen's Empty Keg", description = "A small placard on one of the ends of the keg says,\n\n\"Chen Stormstout-\n\nMay your spirit be raised and always raise your spirits.\"", sourceObjective = "Find someone who knows about Chen's Empty Keg.", progress = "Yes?", completion = "Well, I'll be...\n\nThis was one of Chen Stormstout's kegs. He traveled with Rexxar a long time ago. I haven't seen or heard about him in a kodo's age. I appreciate you bringing this to me, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[821] = { id = 821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen's Empty Keg", description = "Would you like a taste of Chen's namesake? Ahh, the stormstout is a mighty brew. Chen taught the recipe to my mentor, and my mentor passed it on to me. I'll need you to get me a few things, but I can tell you this: the kick is worth it.\n\nBring me 5 savannah lion tusks from any savannah lion, 5 plainstrider kidneys from any plainstrider, and 1 thunder lizard horn from any species of thunder lizard. That should do the trick nicely.\n\nYou can find these ingredients throughout the Barrens.", sourceObjective = "Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet.", progress = "How's the search going?", completion = "Haha... I never thought I'd make more of this stuff ever again.\n\nYou've stirred in me a great sense of nostalgia, {name}. Kind of reminds me of the last time I made a batch of trogg brew. Thank you. The memories warm my stomach.", sourceObjectiveStatus = "unverified-source-field" }
quests[822] = { id = 822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chen's Empty Keg", description = "Good stuff, that stormstout, huh?\n\nI have another recipe that I learned from Chen. Would you be interested? It won't take long to make, and it might be useful if you plan on adventuring some more.\n\nBring me 5 lightning glands from any stormhide, 1 thunderhawk saliva gland from greater thunderhawks, and a kodo liver from any of the Barrens' kodos.\n\nLike I said, this stuff has kick; it's the trogg brew that I mentioned to you before.", sourceObjective = "Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.", progress = "You working hard at finding those ingredients, {name}?", completion = "Haha! I knew you couldn't resist some of this brew. Come back again anytime you want some more, {name}. Just bring me more of the ingredients I had you collect.", sourceObjectiveStatus = "unverified-source-field" }
quests[823] = { id = 823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Orgnil", description = "We at Sen'jin Village are not without our own troubles, and we thank you for your aid.  But the news you bring regarding the Burning Blade could be trouble for everyone.\n\nThere is an orc stationed at Razor Hill, Orgnil Soulscar, who polices Durotar from evils such as the Burning Blade!  Go to Orgnil and tell him of our plight, as well as your news from the Valley of Trials.  He will want to know these things.\n\nRazor Hill lies to the north.", sourceObjective = "Speak with Orgnil Soulscar in Razor Hill.", completion = "Yes?  You have something to report?  Well then, let's have it!", sourceObjectiveStatus = "unverified-source-field" }
quests[824] = { id = 824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je'neu of the Earthen Ring", description = "The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know.\n\nLucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.", sourceObjective = "Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", progress = "Ah, hello there.  I spend a great deal of time studying the water - all the elements really - so much so that sometimes I don't even notice people around me.\n\nIs there something I can help you with?", completion = "This globe... it is most disturbing.  Many of the more powerful elementals receive their power and energy through such devices.  To find one like this nearly intact is one thing - to find it so tainted is another.\n\nI will see that this globe is studied properly by the Earthen Ring.  Perhaps we can bring an end to this corruption of the elements.  Please - accept this as a fair exchange for bringing this globe to the attention of the Earthen Ring.", sourceObjectiveStatus = "unverified-source-field" }
quests[825] = { id = 825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From The Wreckage....", description = "One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep.\n\nIt is no secret that the humans, in alliance with those foul little creatures known as gnomes, have an advanced knowledge of mechanics. We must have a complete understanding of all our potential enemies. And our people will benefit from this new knowledge as well.\n\nSwim through the wreckage, {name}, and retrieve for me the tools of the Alliance.", sourceObjective = "Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast.", progress = "Once we learn how the humans operate their strange machinery, we will stand a greater chance of defeating them in future battles.\n\nWith our new gained knowledge, the Horde only stands to grow in strength.", completion = "Your recovery mission was a success, {class}. I will see to it that these tools get to Orgrimmar with the next caravan.\n\nNicely done.", sourceObjectiveStatus = "unverified-source-field" }
quests[826] = { id = 826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalazane", description = "The witchdoctor Zalazane dwells on the Echo Isles to the east.  They are the isles we once called home.\n\nFrom there he sends his trolls to the mainland, to hex our people and drag more of them under his sway.\n\nHe must be stopped.\n\nDefeat Zalazane and his minions -- former Darkspear trolls, now lost to us.  Bring me his head and I will know his reign of evil is over.", sourceObjective = "Defeat Zalazane.\n\nKill 8 Voodoo Trolls and 8 Hexed Trolls.\n\nBring Zalazane's Head to Gadrin.", progress = "Is Zalazane defeated, {name}?", completion = "With Zalazane gone, our tribe can again sleep in peace.\n\nThank you, {name}.  The Darkspear tribe owes you much.  If you suffer from an ailment, visit my assistant Bom'bay, behind me.  His voodoo is strong...", sourceObjectiveStatus = "unverified-source-field" }
quests[827] = { id = 827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skull Rock", description = "{name}.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.", sourceObjective = "Gather Searing Collars from the cultists in Skull Rock.\n\nBring them to Margoz at his camp.", progress = "Have you yet entered Skull Rock, {name}?  Do you have the Searing Collars?", completion = "Good.  Hiding within these collars is the secret behind the Burning Blade.  And I will uncover that secret...", sourceObjectiveStatus = "unverified-source-field" }
quests[828] = { id = 828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Margoz", description = "One of our Shamans, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the northeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, {name}, I still want you to crush those cultists!", sourceObjective = "Speak with Margoz.", completion = "Welcome, {name}.  Word reached me of your coming, and of your exploits in Durotar.\n\nYou are a {class} of growing skill and renown.\n\nStay on the pure path, and your future will be great indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[829] = { id = 829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeru Fireblade", description = "The Searing Collars you brought me are powerful, demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Neeru in Orgrimmar in the Cleft of Shadow.", sourceObjective = "Bring an Example Collar to Neeru Fireblade in Orgrimmar.", progress = "My most humble greetings, {class}.  How might I help my {race} brother today?", completion = "Ah, and where did you get this?  Good Margoz in Razor Hill sent you to me, did he?\n\nWell, let me take a closer look...", sourceObjectiveStatus = "unverified-source-field" }
quests[830] = { id = 830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral's Orders", description = "You open the aged and weathered envelope and discover an official looking document. You recognize the seal of Admiral Proudmoore.\n\nThis looks important. Perhaps Gar'Thok, the commander of Razor Hill, would be interested in having this information.", sourceObjective = "Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill.", progress = "There is a look of concern on your face, {class}. What have you there?", completion = "This does not bode well at all. You were wise to bring this information to my attention.", sourceObjectiveStatus = "unverified-source-field" }
quests[831] = { id = 831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral's Orders", description = "Humans cannot be trusted. We fought alongside them with a weary heart, knowing they would betray us one day.\n\nAdmiral Proudmoore's death was not enough to stop his legacy of deceit. The human scum had his plans well laid out before he ever met his demise.\n\nHis reign won't even die with Benedict it seems. Who knows how long it will be before the next waves of Proudmoore's men land upon our shores.\n\nWe need to get these orders to Vol'jin in Orgrimmar immediately! He can be found in Thrall's chamber.", sourceObjective = "Deliver Admiral Proudmoore's Orders to Vol'jin in Thrall's chamber in Orgrimmar.", progress = "Can you not see that I am busy? This had better be pressing....", completion = "Countless times I urged the Warchief not to trust the humans, but personal pride is not what is at stake here.\n\nYou have served the Horde honorably, young {class}.\n\nNow excuse me, I must counsel Thrall on these matters at once....", sourceObjectiveStatus = "unverified-source-field" }
quests[832] = { id = 832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Shadows", description = "<Words emanate from the pendant and into your mind.>\n\nGazz'uz?\n\nGazz'uz...report!\n\nThere is word of your discovery in Skull Rock.  You must prepare for an attack!\n\nGazz'uz, I order you to speak!  Speak or I will make sure Neeru Fireblade knows of your presence, and he will descend on you with swift brutality.\n\nDo not test your skills against Neeru...\n\n...Gazz'uz, are you there...?", sourceObjective = "Take this eye to Neeru Fireblade in Orgrimmar.", progress = "You have something vital to report.  I can sense it behind your eyes.", completion = "<Examines the Eye of Burning Shadow.>\n\nIntriguing.  The voice you heard mentioned my name?  I am known for hunting down enemies of our Warchief, but...it is strange that I was singled out.  Stranger still that the Burning Blade cultists from whom you recovered this pendant have a name so close to my own.\n\nI must study this pendant.  I must study and, and must ponder the meaning of its message.\n\nThank you for bringing this to my attention, {name}.  You have done your people a great service.", sourceObjectiveStatus = "unverified-source-field" }
quests[833] = { id = 833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sacred Burial", description = "Only the most valiant tauren are laid to rest at Red Rocks, our sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains.\n\nBut it appears a foul menace has made its way onto our holy land. A band of Bristleback Interlopers is ravaging the grave site and I am too old and past my prime to drive them away.\n\nThey must be driven off with force, {name}.", sourceObjective = "Lorekeeper Raintotem wants you to kill 8 Bristleback Interlopers at Red Rocks.", progress = "The Bristleback Interlopers must be driven away from our sacred burial ground, {name}.", completion = "Well done. You have sent those foul Bristlebacks a clear message. They will think twice before attempting to meddle in this holy spot again.", sourceObjectiveStatus = "unverified-source-field" }
quests[834] = { id = 834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winds in the Desert", description = "I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know?\n\nThe last shipment--they promised it'd get through!--was snatched by the Dustwind harpies of...where was it...Razorwind Canyon?\n\nI gotta have those supplies or I'll never get anything done! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.", sourceObjective = "Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar.", progress = "I'm great at what I do, don't get me wrong, but this is ridiculous! What am I supposed to do, build sand castles?", completion = "Hey, now isn't that just the thing! You've got our supplies back for us. That's great. I'll be able to get back to work just as soon as I can find someone to haul these sacks for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[835] = { id = 835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Lines", description = "Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\"\n\nI can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Drygulch Ravine lies through the eastern part of Razorwind Canyon. If we kill all the harpies there, the routes will be safe.\n\nOf course, there was one other thing that Gazlowe taught me, and that's \"You can get anything done for a price.\" So, going to help me out, {name}?", sourceObjective = "Kill 12 Dustwind Savages and 8 Dustwind Storm Witches for Rezlak near Drygulch Ravine.", progress = "You wouldn't think it from a guy like my boss Gazlowe, but he always seemed to know the score. \"Don't be afraid to take that big step,\" he said.\n\nHarpies won't stop bothering us and the caravans won't stop being attacked unless we do something about it, eh?", completion = "I think I can breathe easy now, knowing that the harpies won't be bothering our supply caravans anymore. And not one moment too soon, either. I hear I'm being sent some fun little toys with the next shipment!\n\nYou're pretty good at what you do, {name}, you ought to track down my boss in Ratchet. I'll bet he could find some work for you.\n\nOh, and don't worry, I wouldn't forget to pay you for the service you provided me.", sourceObjectiveStatus = "unverified-source-field" }
quests[836] = { id = 836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue OOX-09/HL!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, some big rocks that obscure visibility! That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", sourceObjective = "Escort OOX-09/HL to safety, then report to Oglethorpe Obnoticus in Booty Bay.", completion = "Oh, YOU'RE the great savior of OOX-09/HL!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance {name}, my robots and I are in your debt!", sourceObjectiveStatus = "unverified-source-field" }
quests[837] = { id = 837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encroachment", description = "When we arrived, the Razormane quilboars possessed much of the land, and proved a thorn in our sides. Through our efforts we have driven out the largest part of their numbers, but still they remain well-fortified in some areas.\n\nIt has gone on long enough, however. For our own protection, we cannot allow the Razormane any hold in our lands. Their camps can be found to the west of here. Look for the brambles and you will find them. Today we drive them from Durotar, tomorrow, perhaps from all of Kalimdor.", sourceObjective = "Kill 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners and 4 Razormane Battleguards for Gar'Thok at Razor Hill.", progress = "Though they do possess some intelligence and some organization, I find it constantly amazing that the quilboars were able to capture and hold so much territory in Kalimdor. Perhaps they are more crafty an enemy than I give them credit for...", completion = "I will pass along word that the quilboars have been removed from their lairs, and that their structures may be set to fire. The removal of the Razormane from Durotar brings us closer to fully securing the borders of our new homeland.", sourceObjectiveStatus = "unverified-source-field" }
quests[838] = { id = 838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomance", description = "On the island of Caer Darrow lies Scholomance - a school that serves as a stronghold for the Scourge.  Our enemy dwells within, safely allowed to pursue research that strengthens their power.  A door bars the way, and try as we might no entry is to be had without a proper key.\n\nApothecary Dithers is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your value to me as someone who can get things done; I now entrust this task to you.  Speak with him on this matter.", sourceObjective = "Speak with Apothecary Dithers at the Bulwark, Western Plaguelands.", completion = "Yes, {class}, the High Executor mentioned you might be the one to trust in the matter of the key.  I've dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire one that will let you past the front door at will.\n\nThis task will not be easy, but such tasks seldom are.  You most assuredly look like the type to know this as fact.", sourceObjectiveStatus = "unverified-source-field" }
quests[840] = { id = 840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conscript of the Horde", description = "Hmm, you look pretty strong.\n\nListen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance.\n\nTake this recruitment letter to Kargal and see if he'll sign it.", sourceObjective = "Follow the western road from Razor Hill to the Barrens over a bridge.\n\nStop at the orc outpost across the bridge.\n\nGive Kargal Battlescar at the Barrens outpost your recruitment letter.", progress = "What do you want, pup? If you're not here for recruitment, I don't have time for you.", completion = "Oh, so Takrin sent you? He's an excellent scout, I'm not sure what I'd do without him.\n\nI'll sign your recruitment letter, but what we really need is someone at the Crossroads.", sourceObjectiveStatus = "unverified-source-field" }
quests[841] = { id = 841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Power Source?", description = "Let me guess - you didn't get whatever world-ending, nefarious deed you were doing done in time.  No wait, better still... you dropped it in the sand!  Well, whatever the reason, I do have additional power sources I will sell to you.  This time, however, it will cost you ten, YES TEN Wastewander Water Pouches!\n\nTimes are tough all around, {name}, and power sources don't grow on trees!  Hrm, but what if they did.  Maybe we could MAKE a power source tree...", sourceObjective = "Bring 10 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan in exchange for another power source.", progress = "Well, have you got the ten water pouches?", completion = "Very well, here is another power source.  I highly recommend you using it properly this time, unless you are eager to spend ten more water pouches for another water source.", sourceObjectiveStatus = "unverified-source-field" }
quests[842] = { id = 842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossroads Conscription", description = "Take this signed recruitment letter to the Crossroads.\n\nSergra Darkthorn, curse her hide, is in charge there. She's a nasty shaman who will talk your head in circles before she lets you do anything useful. Thrall is convinced she's something special, but I'm not so sure.\n\nYou'll just have to decide for yourself, pup...", sourceObjective = "Follow the western road from Kargal's Far Watch Outpost.\n\nAt the T intersection, turn left and follow the road south. \n\nFind Sergra Darkthorn at the crossing of roads within the Crossroads.", progress = "Well well well, what do we have here? Has Kargal deemed me worthy of another recruit?", completion = "Alright, {name}. You want to earn your keep with the Horde? Well there's plenty to do here, so listen close and do what you're told.\n\n I see that look in your eyes, do not think I will tolerate any insolence. Thrall himself has declared the Hordes females to be on equal footing with you men. Disrespect me in the slightest, and you will know true pain.", sourceObjectiveStatus = "unverified-source-field" }
quests[843] = { id = 843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gann's Reclamation", description = "In solitude I wander these roads.\n\nThe dwarves of Bael Modan show no respect for my land. Horrendous blasts drive holes deep into the ground as noisy machines rip apart the hills. Lands which once served as home and provider to my tribe are now riddled with destructive dwarves.\n\nAttempts at reaching a diplomatic resolution have failed. Now is the time for decisive action.\n\nDrive the dwarves from the Bael Modan excavation by force and bring to me the journal of their leader, Prospector Khazgorm.", sourceObjective = "Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.\n\nBring Khazgorm's Journal to Gann Stonespire.", progress = "Many innocent tauren lost their lives or were forced off their ancestral birthplace when the dwarves of Bael Modan arrived. My land must be reclaimed!", completion = "Khazgorm met the fate he earned. I feel no remorse for the fool. He was an infidel on these lands.\n\nMay his death serve as a warning to all those who threaten to disrupt our way of life.\n\nNow let me take a moment to study the dwarf's journal....", sourceObjectiveStatus = "unverified-source-field" }
quests[844] = { id = 844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plainstrider Menace", description = "Your first prey will be easy.\n\nThe plainstriders to the east have been harassing our food supplies and have become a nuisance.\n\nPut down the plainstriders and return to me with their beaks.", sourceObjective = "Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads.", progress = "Have you collected the plainstrider beaks?", completion = "Very good, {name}.  With the plainstriders gone we'll have an easier time keeping our supply chains intact.  And I hope you learned a few tricks out there in the Barrens, for your next prey has a little more fire in its blood than the plainstriders...", sourceObjectiveStatus = "unverified-source-field" }
quests[845] = { id = 845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zhevra", description = "The zhevra, although not the fiercest beast in the Barrens, are a shade tougher than the plainstriders.  Don't worry -- we'll send you against bigger prey in good time, but for now your teeth could use a little more cutting.\n\nHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.", sourceObjective = "Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads.", progress = "How many zhevra have you slain?", completion = "Not bad, {name}.  Those zhevra hold a lot of strength in their legs.  A sharp kick from them can knock even a tauren on its haunches!\n\nIt looks like you have some strength in you too.  Are you ready for a real challenge?", sourceObjectiveStatus = "unverified-source-field" }
quests[846] = { id = 846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge of Gann", description = "It is clear the prospector depended on explosives and those noisy vehicles to rip the ground apart. We can expect a new foreman to take over soon.\n\nI want to give the dwarves a taste of their own medicine. According to these plans if we combine nitroglycerin with wood pulp and sodium nitrate we can create an explosive charge. The rifleman, soldiers and officers in the Keep are known to have the supplies.\n\nCollect these items and bring them to me. I will fashion a charge that the dwarves won't forget!", sourceObjective = "Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.", progress = "I see you are back, {name}.\n\nWhile Khazgorm's death might delay the digging in my ancestral lands some, it will by no means bring a total end to the destruction.\n\nThe Keep at Bael Modan is an increasing military threat. Built to defend the dig site, it is now poised for offensive force as well.\n\nIf you have the ingredients I requested, I can fashion a charge that will make the hasty dwarves reconsider their actions here in the Barrens.", completion = "I see you are quite industrious, {class}.\n\nNo doubt we shall soon have a fitting surprise for those dwarves.", sourceObjectiveStatus = "unverified-source-field" }
quests[847] = { id = 847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guile of the Raptor", description = "This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.", sourceObjective = "Speak with Tor'gan at Hammerfall in Arathi Highlands.", completion = "When the enchantment wears off, I will speak with Gor'mul. My thanks to you for your help in returning Gor'mul to the land of the living. I have no doubt he thanks you greatly as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[848] = { id = 848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Spores", description = "The oases of the Barrens hide a mystery.  Life energy flows from their waters, invigorating the plants and beasts that drink it.\n\nInvigorating, and altering.\n\nThere is a mushroom that grows near these oases.  Its spores hold properties that we, the apothecaries of Lordaeron, find useful.\n\nBring me these spores and you will earn our gratitude.", sourceObjective = "Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads.", progress = "Do you have the spores, {name}?  There is a concoction I must send to my associate in Thunder Bluff, which requires the spores...", completion = "Ah, yes.  These are good specimens.  Potent.\n\nI am Forsaken, and we honor our contracts.  Here is your reward, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[849] = { id = 849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge of Gann", description = "Following Khazgorm's plans it should be no problem to fashion an explosive charge\n\nAh, there we go.\n\nNow, {name}, I am going to entrust you with a special task. Take this explosive stick and use it to blow up the flying machine at Bael Modan.\n\nNot only is the flying machine a key part of the site's infrastructure it also serves as a weapon of war. More importantly it is an icon of power and an insult to the memory of my tribe.\n\nMake me proud by completing this heroic task and you shall be rewarded.", sourceObjective = "Destroy the flying machine at Bael Modan and return to Gann Stonespire.", progress = "Once the dwarven flying machine has been destroyed I will feel the sweet satisfaction of revenge.", completion = "You have done well, {name}! May you be revered in Thunder Bluff as a defender of sacred tauren lands and a champion of the lost tribe.", sourceObjectiveStatus = "unverified-source-field" }
quests[850] = { id = 850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kolkar Leaders", description = "The centaurs have plagued the Tauren for years.  And recently, the Kolkar centaurs of the Barrens have grown into a real threat.  Normally they were disorganized in these lands, but new leaders have risen among them.  Rallying them.\n\nTo preserve our holdings here, these centaur leaders must be destroyed.\n\nBring me the head of Barak Kodobane.  He camps near the Forgotten Pools to the north.\n\nDefeat him, then return to me.", sourceObjective = "Bring Barak's Head to Regthar Deathgate, west of the Crossroads.", progress = "Hello, {name}.  Do you have Barak's Head for me?", completion = "Well done, {name}.  The centaur are low, brutish creatures, but a few have the wit and vision to lead.  And those are the most dangerous.\n\nBarak was such a centaur.  It is good that he is dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[851] = { id = 851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verog the Dervish", description = "The centaur Verog the Dervish wanders the Barrens, and will be difficult to find.  But he is based at the centaur command tent at the Stagnant Oasis to the southeast.  It may be possible to draw him to you.\n\nTravel to the Stagnant Oasis to the southeast and attack centaur near the command tent.  It will be dangerous, but if you can kill enough centaur then they should raise an alarm.  And Verog will come.\n\nBring me his head and I will place it with Barak Kodobane's.", sourceObjective = "Bring Verog's Head to Regthar Deathgate, west of the Crossroads.", progress = "Did you find Verog, {name}?", completion = "Very good.  You must have really stirred up those centaur -- our guards spotted activity down near the Stagnant Oasis, which was probably you.\n\nYou should be proud of your deed, {name}.  There is much bravery in you.", sourceObjectiveStatus = "unverified-source-field" }
quests[852] = { id = 852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hezrul Bloodmark", description = "Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens.  He is fierce, brutal and cunning.  Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us.\n\nSo kill him.  As with Barak and Verog, bring me Hezrul's Head.\n\nHe leads his people from the Lushwater Oasis, to the south.", sourceObjective = "Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.", progress = "Is Hezrul defeated, {name}?", completion = "I commend you, {name}.  These centaur are undisciplined and cannot focus their rage as the orcs can, but they are fierce nonetheless.  In defeating them, your valor is proven.", sourceObjectiveStatus = "unverified-source-field" }
quests[853] = { id = 853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apothecary Zamah", description = "I have rendered the spores you gave me into an emulsion.  I must now send it to my associate, Apothecary Zamah.  If you were to carry this to her, she can offer you something from our stores of alchemical goods.\n\nShe is in the Pools of Vision, a cave beneath the shamans of Thunder Bluff.  The path to this cave is well hidden, but you may find it on the Spirit Rise bluff.\n\nDo hurry.  This emulsion will maintain its potency for only a short time, and must be resealed and processed before then.", sourceObjective = "Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.", progress = "You have something from Apothecary Helbrim?", completion = "Ah, the spores from the Barrens that Helbrim was gathering.  He garnered your aid in delivering them?  Good.\n\nAnd the emulsion is still potent, so you must have wasted no time in the delivery.  Well done, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[854] = { id = 854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to the Crossroads", description = "I have foreseen your arrival, young {class}. Though perhaps you are not so young anymore.\n\nI think that it is time for you to move deeper into this land. I can sense that you are destined for great things.\n\nIt is the Crossroads that you must seek out, for our lives with the orcs have become intertwined and they need assistance. Continue down this road towards the east and follow it north to the Crossroads. Find Thork within its walls, he has the Earthmother's blessing.", sourceObjective = "Speak with Thork at the Crossroads in the Barrens.", completion = "It is good to see that more of our {race} allies have come to assist us from as far away as Thunder Bluff. Again, I welcome you.", sourceObjectiveStatus = "unverified-source-field" }
quests[855] = { id = 855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Centaur Bracers", description = "The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops.  And so, I have a bounty task for you.\n\nWhile in Kolkar territories, slay their warriors and collect centaur bracers.  Return when you have a heap of bracers and the Horde will reward you well.", sourceObjective = "Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads.", progress = "How goes your hunting, {name}?", completion = "Nicely done.  I'm sure you've struck fear into the surviving centaurs, {name}.  If they have sense, they'll now calm themselves and stop their advances.\n\nBut I don't think they will, and that is unfortunate.\n\nUnfortunate...for them.", sourceObjectiveStatus = "unverified-source-field" }
quests[857] = { id = 857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tear of the Moons", description = "The power was mine! In my very hands! And I want it back! Back I say!\n\nThose dirty excavators uncovered it... so beautiful it was. Deemed the Tear of the Moons, it was the first great discovery we made at Bael Modan.\n\nIt should have been mine! Mine I say!\n\nGeneral Twinbraid grew jealous of the power it gave me. He locked it away in the Keep. Called it cursed, he did! The fool!\n\nOthers wanted it and they had to be stopped! That fiend Twinbraid drove me off.\n\nNow I want it back. Back I say!", sourceObjective = "Feegly the Exiled wants you to retrieve for him the Tear of the Moons.", progress = "Where is the Tear of the Moons? I need it now! Need I say!", completion = "At last, the power is mine again! Mine I say!", sourceObjectiveStatus = "unverified-source-field" }
quests[858] = { id = 858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignition", description = "I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem.\n\nWe need to get out of here on the double! Go up to the control room at the top of the derrick, the supervisor should have a key for this shredder.\n\nHelp me out here!", sourceObjective = "Get the Ignition Key and bring it to Wizzlecrank.", progress = "Quick, we need to get out of here before someone gets suspicious!", completion = "Yep, this looks like the right key. Let me just make sure I know how to work this thing...\n\nHmm... rotation control... This regulates speed and stability... fine arm movement control. Just look at this! I can't believe the Venture Company could design something this much better than ours. I've got to get this back to Ratchet!", sourceObjectiveStatus = "unverified-source-field" }
quests[860] = { id = 860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sergra Darkthorn", description = "If you wish to walk the hunter's path, then your journey leads to the Barrens.  Its beasts are strong-willed and fierce.  You will learn much by hunting there, and your spirit will grow.\n\nSpeak with Sergra Darkthorn.  She will be your first guide in the Barrens.\n\nSergra is at the Crossroads.  To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks.  And have care as you travel--the Barrens holds great danger for the unprepared and unwary.", sourceObjective = "Speak with Sergra Darkthorn at the Crossroads in the Barrens.", completion = "You want to hunt in the Barrens?\n\nYour eyes are eager, and young.  They're not yet squinted from tracking your prey across this land's dry plains.\n\nBut worry not. We'll toughen your body and your mind.  And we'll teach you that there is more to hunting than finding and killing your quarry.\n\nPrepare yourself.  Your journey begins.  Now.", sourceObjectiveStatus = "unverified-source-field" }
quests[861] = { id = 861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Way", description = "You are eager to explore, I can tell.  I too had the lust to wander, once...\n\nWander, and hunt.  For hunting is a Tauren's greatest honor.\n\nIf you truly wish to follow the ways of the hunter, then Melor Stonehoof can show you the path.  He is in Thunder Bluff, on the Hunter's Rise.\n\nAnd to show him your skill and resolve, bring him the claws of the flatland prowlers of Mulgore.  They are tough and cunning -- fitting prey for a young {class} on the hunter's path.", sourceObjective = "Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff.", progress = "Greetings.  There is an air about you that tells me much.  Do we have business, you and I?", completion = "Skorn Whitecloud is a wise {race}.  He has hunted for years and years, and although his body is old, his spirit burns fiercely.  We are honored to have him with us.\n\nIf Skorn sent you to me, then  you too must have the hunter's spirit.  And to have gathered these claws shows your burgeoning skills.\n\nPerhaps you are ready to walk the path.", sourceObjectiveStatus = "unverified-source-field" }
quests[862] = { id = 862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dig Rat Stew", description = "A {class} like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long.\n\nTell you what, I'll fix you up a nice stew. Just need a few dig rats.\n\nSeems those filthy dwarves at Bael Modan are overrun with everyone's favorite feast. Now head on down south to Bael Modan and bring me back some dig rats.\n\nYou can't call yourself a seasoned adventurer until you've spent some time killing rats! Haw!", sourceObjective = "Bring 8 Dig Rats to Grub east of the Crossroads.", progress = "Whack enough dig rats yet, {name}?", completion = "Normally I don't like to eat these rodents when they're so.... so... ripe. Like to let them rot for a few weeks to really bring out the flavor. But you look so hungry.\n\nLet me fix you some Dig Rat Stew. Ah, there we go.\n\nHere you go!", sourceObjectiveStatus = "unverified-source-field" }
quests[863] = { id = 863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Escape", description = "I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?", sourceObjective = "Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet.", completion = "Hopefully we'll be able to get something of value from the wrecked shredder prototype... my time's running out! I'll dispatch a salvage team to Wizzlecrank's location on the double.\n\nOh, let me give you something for your trouble, too.", sourceObjectiveStatus = "unverified-source-field" }
quests[864] = { id = 864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Apothecary Zinge", description = "\"Here you go, the power source is safely removed and the data is preserved.  Well, safe journeys and all that.  Hope the nefarious science experiment worked out for you and all.\"\n\nThe goblin turns away from you to attend to the demands of the Gadgetzan Water Company.  You secure the sealed testing kit for the journey back to the Undercity.  Apothecary Zinge waits for you and the sealed field testing kit there.", sourceObjective = "Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity.", progress = "Welcome back.  At least, welcome back if you have returned with a sealed testing kit.  Otherwise, I will pretend not to notice your utter incompetence and spare my wrath from you until you do as you have been tasked and accomplish my task.", completion = "I will analyze this data immediately.  Perhaps Keever's insanity will prove to be my genius after all.\n\nAs for you...  you are useful to me, and I reward quite well those who remain useful.  Take this item, this coin, and most importantly my thanks along with them.\n\nCheck back with me from time to time - I wager that our working together on this project is not at an end.", sourceObjectiveStatus = "unverified-source-field" }
quests[865] = { id = 865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Horns", description = "The raptors of the Barrens are smarter than raptors in other lands.  And I think all that smarts is hiding in their horns!  If so, then I could grind their horns into powder and use it to make \"smart drinks.\"  I could sell them for a fortune!!!\n\nAnd you can help me.  Find me intact raptor horns from sunscale scytheclaws.  They roam in the southern Barrens, and in the northern Barrens near the border of Ashenvale Forest.", sourceObjective = "Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.", progress = "Did you get the horns, {name}?  Those things are going to make me a fortune!", completion = "Great, you got them!  Now I just need to ground them down and mix them with some wine, and...", sourceObjectiveStatus = "unverified-source-field" }
quests[866] = { id = 866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root Samples", description = "The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different.\n\nI want to study those differences... to see if they're exploitable!\n\nIf you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.", sourceObjective = "Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.", progress = "Hello, {name}.  Did you get those root samples?", completion = "Yes yes, these are very nice!  I will grow specimens from these roots and study them.  I hope to find new properties from them.  Hidden, valuable properties...!\n\nAnd don't worry -- if I do then you'll be the first to know.  Because I'll need someone to gather more!", sourceObjectiveStatus = "unverified-source-field" }
quests[867] = { id = 867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpy Raiders", description = "The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers.\n\nI've been snooping around their nests and figured out who leads who. The most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top.\n\nI'll start you off slow, take out Witchwing Harpies and Witchwing Roguefeathers in the Northwest and bring me 8 Witchwing talons. That should be a good start...", sourceObjective = "Collect 8 Witchwing talons.\n\nReturn them to Darsok Swiftdagger at the Crossroads.", progress = "Cut up enough of them yet? Keep slicing and taking trophies. I want 8 Witchwing talons.", completion = "Oh, these are nice. Real nice... Good job, {name}. I look forward to seeing more of your work in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[868] = { id = 868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Hunt", description = "Hey, {name}. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar.\n\nOne object of my studies are the insect-like creatures found to the south in the Field of Giants. We know little of the creatures, so I be makin' it a point to discover more. They seem to have intelligence to them, more so than any normal animal.\n\nTake this digging claw and collect some of the creatures' eggs from their mounds, but be careful: if alerted, they will attack you.", sourceObjective = "Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.", progress = "Be careful with the eggs you find, {name}. If they break, they be no good to me.", completion = "You please me, {name}. The eggs and the tool. Well done.\n\nAnd for your reward...", sourceObjectiveStatus = "unverified-source-field" }
quests[869] = { id = 869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Thieves", description = "Not long ago, a shipment of silver was stolen from our guard tower.  It was meant as payroll to the Crossroads' guards, and we want that silver back.\n\nThe strange thing is... we caught one of the thieves on the night of the theft.  And... it was a raptor!  Unbelievable!\n\nI don't know what raptors would want with silver.  But I don't care -- I want the raptors dead so they won't steal from us again!\n\nHunt raptors in the Barrens.  Collect for me their heads!", sourceObjective = "Bring 12 Raptor Heads to Gazrog at the Crossroads.", progress = "Do you have those heads, {name}?", completion = "You got rid of the raptors!\n\nThank you, {name}.  You are a {class} of worth.", sourceObjectiveStatus = "unverified-source-field" }
quests[870] = { id = 870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten Pools", description = "Long ago, the Barrens was a lush place, teeming with life.  But war and cataclysm raged across the land, scorching it and leaving a dry husk.  Such is the way of things, and it saddens my heart.\n\nBut within the past few years, new oases have formed in the Barrens, and life stirs.  And deep down, we druids sense a power leaking its way to the surface.\n\nWe must find its source.  Travel to the Forgotten Pools, northwest of the Crossroads.  Search its waters for a source of power, then return here.", sourceObjective = "Report back to Tonga Runetotem with your findings.", progress = "Have you been to the Forgotten Pools, {name}?  Did you find anything?", completion = "You found a fissure in the earth, with gases bubbling from it?  Strange.  This may be an answer to our questions, but we cannot yet be sure.\n\nBut it is a clue.  And I am grateful that you found it.", sourceObjectiveStatus = "unverified-source-field" }
quests[871] = { id = 871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt the Attacks", description = "All the quilboars are our enemies, {name}. Some just prove to be more of a nuisance than others.\n\nThe Razormane tribe has been attacking our supply lines from Durotar, causing us no end of annoyance. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.\n\nStart in the northeast towards Durotar. You can always tell their dens from the huge thorny vines that come up from the earth. Seek them out, and slay them.", sourceObjective = "Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads.", progress = "The longer it takes to stop these attacks, the harder it will be to provide supplies for the people of the Crossroads.", completion = "You have done well, {name}. Those insolent quilboars will finally learn that the might of the Horde is not to be ignored.", sourceObjectiveStatus = "unverified-source-field" }
quests[872] = { id = 872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Disruption Ends", description = "One of my scouts witnessed an attack on a caravan from Durotar, {name}. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout. He was seen northeast of here, just south of the road from Durotar. If the threat is to be ended, then Kreenig must die.\n\nTo be sure the attacks cease, though, I say we add insult to their injury. Kill Kreenig along with more of their tribe, and return to me when you have his tusk.", sourceObjective = "Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout.\n\nThen bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads.", progress = "Cut off the head of their leader, and chaos ensues, {name}. Learn this lesson well. It will aid you in the future.\n\nThe boars will flounder without direction, and we will be able to take back the Barrens.", completion = "Well done, {name}. With Kreenig's death, there will be a definite decline in the attacks on our caravans.\n\nYour people should be proud to count you among them.", sourceObjectiveStatus = "unverified-source-field" }
quests[873] = { id = 873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Isha Awak", description = "The grand Isha Awak is lord of these waters.  Great is his strength, and solemn his pride.  The humans on the coast fear him, for he has consumed many of their number.\n\nBut I do not fear him.  I am grateful he is here.  He is a worthy challenge, and honorable prey.\n\nIf you are ready, then swim out and search for Isha Awak, the Deep Doom.\n\nHis spirit dwells in his heart, and to hear its beat is to know your fate.", sourceObjective = "Bring the Heart of Isha Awak to Mahren Skyseer.", progress = "Fear not the waters, {race}.", completion = "You now are one with Isha Awak, {name}.  His spirit is with you.  He lurks in your eyes...\n\nEyes that, one day, will learn to see.", sourceObjectiveStatus = "unverified-source-field" }
quests[874] = { id = 874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mahren Skyseer", description = "You have hunted the beasts of the Barrens.  Your spirit is strong.  But a hunter must always be prepared.  A true hunter can stalk prey down any path.  Mountains and swamps will not sway <him/her>.\n\nNot even the sea.\n\nFind my sister, Mahren.  She hunts the great water beasts along the coast.  She will be your teacher in their ways.\n\nBut be wary in your search for her, for the Barrens' coast is held by humans.", sourceObjective = "Speak with Mahren Skyseer.", completion = "My brother sent you, did he?  Then you must have proven yourself to him.  If you have earned the respect of Jorn, then you have my respect as well.\n\nAre you ready to tread farther down the hunter's path?", sourceObjectiveStatus = "unverified-source-field" }
quests[875] = { id = 875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpy Lieutenants", description = "Hahaha, {name}. Back for more? Good, I like to hear that.\n\nThis time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy.\n\nMake sure they die painfully, {name}. We want those harpy wenches to know the idiocy of picking fights with the Horde.", sourceObjective = "Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads.", progress = "Do you have 6 Harpy Lieutenant Rings yet? Justice must be dealt to them for their vicious attacks on the Horde.", completion = "Excellent work my friend. I think you'll go far within the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[876] = { id = 876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serena Bloodfeather", description = "You did so well with the lieutenants and underlings that I'd like you to do one last thing for me.\n\nSerena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago. Apparently, these attacks on the Horde caravans are revenge for her sister's death.\n\nI need you to slit her throat and bring me back her head. I want to place it on the next caravan we send out... Give those harpies something to think about.", sourceObjective = "Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads.", progress = "You're not getting anything until I see Serena's head.", completion = "HA! Well done, {name}! Very well done... I wasn't sure you were up to the task, but you've proved yourself quite the cut-throat. Thank you again for helping us suppress the Harpy epidemic. Here is your reward, use it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[877] = { id = 877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stagnant Oasis", description = "Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens.  If so, then perhaps the fissures are the oases' source of life.\n\nWe must test this.\n\nHere, take these seeds.  They are dead and infertile, but take them to the Stagnant Oasis to the southeast.  If there is a fissure there, then place the seeds within it...and observe.", sourceObjective = "Return to Tonga at The Crossroads, after investigating the Stagnant Oasis.", progress = "Have you been to the Stagnant Oasis?  Was there a fissure beneath its waters?", completion = "Your findings are amazing!  The seeds I gave you were dried, and dead.  Whatever rests under these oases can create life from nothing!\n\nWe must study this more...", sourceObjectiveStatus = "unverified-source-field" }
quests[878] = { id = 878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tribes at War", description = "You must strike my enemies. <snort> You must help Mangletooth and the Razormane by weakening the Bristlebacks. Both tribes are very spiritual--tied to the earth and its power. <snort> It gives us strength in all things... especially war.\n\nIf you want to find out who really causes Thork <snort> and the Horde such anguish, then help Mangletooth! You attack the spiritual leaders of the Bristlebacks to the north; weaken them so the Razormanes can defeat them and rule the Barrens.", sourceObjective = "Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.", progress = "More information <snort> for the Horde when you've killed the Bristleback's wise ones, {race}.  Not a moment earlier! Mangletooth is no fool.", completion = "Yes, yes... filled with joy because finally <snort> the Bristleback know my tribe's pain, {race}. That is how I should feel, but that  is not the case.\n\nYou aid your people and they honor you. Mangletooth aids his people, and what do they do? They turn their backs on him. They forget him and leave him to rot in cage!\n\nI aid them even from locked behind bars and they send no one to save me!", sourceObjectiveStatus = "unverified-source-field" }
quests[879] = { id = 879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal from Within", description = "Three of my tribe came out of the Kraul to lead the raids against the Horde, {race}. <snort> They are ruthless and cunning, and if you defeat them, then your Crossroads and even most of the Barrens will learn peace... <snort> at least from the Razormane tribe. <snort>\n\nNak, Kuz, and Lok Orcbane are the ones you seek. They are far to the south  of the Barrens. One is a spell caster, another a tracker, and their leader, the one called Orcbane, <snort> a warrior. Kill them, {race}, like they have killed me.", sourceObjective = "Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.", progress = "How goes your hunt, {race}? \n\nThork thinks he knows the truth about who leads the raids against his people,  but he shall learn how wrong he is if you are successful.\n\nMy death is inescapable, but you have caused great pain to my enemies, so Mangletooth regrets nothing.", completion = "It is done then. Better it ends this way, says Mangletooth. <snort> They should have <snort> made sure I was dead when they turned their backs on me instead of leaving <snort> me here in this forsaken cage.\n\nThere is but one task left for you to finish, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[880] = { id = 880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altered Beings", description = "Your findings are incredible, {name}.  These oases hold properties that must come from an outside source.  Or perhaps an inside one.\n\nI want to know how these fissures are affecting the beasts who drink from the oases' water.\n\nHunt oasis snapjaws at the Lushwater and Stagnant Oases.  Bring me their shells so I may examine them.", sourceObjective = "Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.", progress = "How goes your collection?  Did you get the shells?", completion = "Thank you, {name}.  Studying the beasts of an area can tell much about the area itself.  We shall see what tale these shells tell.\n\nPlease accept my gratitude for your aid ... and perhaps you can use these coins.  I find that I do not need them.", sourceObjectiveStatus = "unverified-source-field" }
quests[881] = { id = 881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echeyakee", description = "Whitemist, Echeyakee in the Tauren tongue, is the king of the savannah cats.  He hunts with such stealth, they say he's like a thin, white mist on the earth.  And he kills so fast his prey have no time for fear, or pain.\n\nThe Tauren say he is both mercy and death.\n\nYou will learn if that's true, for I now set you on the path to hunt Echeyakee.  His lair is northeast of the Crossroads, among the bones of giant Kodo\n\nGo.  Blow this horn when you reach his lair.  Blow the horn, and he will come.", sourceObjective = "Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads.", progress = "The great cat calls to you, {name}.", completion = "You've beaten Echeyakee, and though his days of hunting are over... his spirit is with you.  He will show you the strength found in subtlety, and the honor in mercy.\n\nYour path is still long, {class}.  Let's hope you stride it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[882] = { id = 882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishamuhale", description = "Ishamuhale, Speartooth, is the fiercest sunscale raptor of the Barrens.  He does not hunt for sport, nor for food.  He hunts because hunting is his passion.  He kills because it is his nature to kill.\n\nAnd you will learn of his nature, {name}, for your path now follows the taloned tracks of Ishamuhale.\n\nBegin the hunt.  Slay his favorite prey, a zhevra, then bring its carcass to the dead tree northwest of Ratchet.  Ishamuhale will smell the carcass and be drawn to it.\n\nBe ready when he comes.", sourceObjective = "Bring Ishamuhale's Fang to Jorn at Camp Taurajo.", progress = "{name}, have you bested Ishamuhale?", completion = "This fang is merely a token, but what it represents is profound.\n\nIshamuhale's strength is in you, {name}.  May you use it with temperance.  That is your burden.\n\nThat is your honor.", sourceObjectiveStatus = "unverified-source-field" }
quests[883] = { id = 883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lakota'mani", description = "The Hoof of Lakota'mani is a symbol of the strength of the great kodo.", sourceObjective = "Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.", progress = "{name}, when you approached I saw a new power in your stride.  Tell me -- has your spirit met with the great Lakota'mani?", completion = "Lakota'mani is called \"Earthshaker\" in our language, and his steps are like gathered thunder.  He is with you now, and his courage mingles with yours.  Together there is no conflict you cannot face.\n\nWalk tall, {name}.  Walk tall, Earthshaker.", sourceObjectiveStatus = "unverified-source-field" }
quests[884] = { id = 884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Owatanka", description = "When touched, sparks fly from the tailspike of Owatanka.", sourceObjective = "Bring Owatanka's Tailspike to Jorn at Camp Taurajo.", progress = "{name}, there is a new power behind your eyes!  You have met with the mighty Owatanka, have you not?", completion = "The thunder lizard Owatanka is called \"Bluebolt\" by the tauren, for within him resides a speed that belies his size.  It is said that lightning struck Bluebolt long ago and, fed from the sky's rage, the great beast's energy is without limit.\n\nMay his energy flow through you, {name}.  For you now keep pace with Owatanka.", sourceObjectiveStatus = "unverified-source-field" }
quests[885] = { id = 885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Washte Pawne", description = "The feather of Washte Pawne is painful to the touch.", sourceObjective = "Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.", progress = "There is new resolve within you, {name}.  A resolve born from pain...\n\nAre you burdened with the death of Washte Pawne?", completion = "The thunderhawk is a rare beast of the Barrens, and its death can portend great fortune, or great doom.\n\nBut Washte Pawne, called \"Spirit Biter\" in Taurahe, can bring neither... or both.\n\nThe pain you felt from hunting Spirit Biter is the pang all feel who make great gains at great costs.  The sting you felt is the pain of regret.\n\nBut I can see you have conquered this.  You have learned that regret turns to wisdom, and that through pain one gains strength.\n\nYou have learned much, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[886] = { id = 886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Barrens Oases", description = "The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore.\n\nTonga Runetotem was sent to discover the source of this power, but we fear he will need aid.\n\nTravel to the Barrens and speak with Tonga.  He will be at the Crossroads.  To reach there, take the road east out of Bloodhoof village.  Enter the Barrens, then turn north when the road forks.  Continue north and  you will find the Crossroads.\n\nAnd do not leave the road, {name}, for the Barrens is a harsh land.", sourceObjective = "Speak with Tonga Runetotem at the Crossroads in the Barrens.", completion = "My brethren in Thunder Bluff were wise to send you, young {class}.  For the mystery of the Barrens is one that I alone cannot unravel.\n\nWith your aid, let us hope we can find answers to our questions.", sourceObjectiveStatus = "unverified-source-field" }
quests[887] = { id = 887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Southsea Freebooters", description = "I sure wish Vice Admiral Grezzlik did a better job of keeping the seas safe for our trading vessels. With all the gold the trade princes have poured into the Trade Fleets, it ticks me off to see so many pirates running willy-nilly, raiding my ships and stealing my goods!\n\nI heard that the Southsea Freebooters have set up a camp just south of here. They've been a real thorn in my side and if Grezzlik won't take care of them, well, maybe you can help me get rid of them.", sourceObjective = "Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet.", progress = "I don't even want to think about the profits I've lost from pirate raiding, and now they set up camp on my doorstep? It's getting out of hand, Undermine's got to do something about it.", completion = "You did good, kid. A little more work like that, and it'll be one less thing I'll have to worry about. Hopefully they'll be convinced that they should relocate their operation elsewhere.\n\nIn the meantime, there is the small matter of getting back the goods they stole from me!", sourceObjectiveStatus = "unverified-source-field" }
quests[888] = { id = 888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Booty", description = "While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have!\n\nAs you see, my observatory is ready to go, but it needs the smaller of the two lenses. The first arrived by caravan from Durotar, but the second was bound by ship, and never arrived. Also, I never got my boot shipment from Drizzlik in Booty Bay!\n\nHead down to the pirate camp and see if you can find them.", sourceObjective = "Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.", progress = "Did you find my things, {name}?", completion = "It's a relief to get all this stuff back, so thanks for your help, {name}. You know, I could use a {race} like you to help out with my operation here. If you're ever looking for work, don't forget about how well Gazlowe pays for service!", sourceObjectiveStatus = "unverified-source-field" }
quests[889] = { id = 889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Wind", progress = "Bring Mangletooth 10 blood shards and I will bless you with great speed. You will run with zhevra and the wind will be jealous of you.\n\nIt will not last long, but it should be enough to help you travel throughout the Barrens.", completion = "Good. Go with Agamaggan's spirit as your guide, {race}. Return to me if you desire more of Agamaggan's magics." }
quests[890] = { id = 890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Shipment", description = "I've been waiting forever for my last shipment of goods from Booty Bay! I'm pretty sure that it must have been stolen by the Freebooters, but just to make sure, will you go down to the dockside and ask Dizzywig if my goods were already put into my warehouse without my knowledge?\n\nHere, take my ledger down to Dizzywig and have him double check my inventory records against his logs.", sourceObjective = "Bring Gazlowe's Ledger to Wharfmaster Dizzywig.", progress = "Wares to send on the next ship, {name}?", completion = "Ah, Gazlowe sent you, did he? Just a moment, let me take a look here and check my own logs and make sure I didn't have Gazlowe's shipment sent to the wrong place.\n\nBet he's waiting for those boots from Drizzlek...", sourceObjectiveStatus = "unverified-source-field" }
quests[891] = { id = 891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guns of Northwatch", description = "Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold!\n\nThose pests must be dealt with. Their paranoia has them in a state of frenzy. Trigger happy, reckless louts are shooting at anything in their sights.\n\nTravel south along the Merchant Coast to the Hold and lay siege to their forces. Bring me the medals of their soldiers as proof. And for the love of my fleet, slay Captain Fairmount and her overzealous cannoneers!", sourceObjective = "Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe.", progress = "My fleet is in peril with Captain Fairmount and her damned cannoneers blasting away from Northwatch Hold. I want her soldiers to pay as well. Fill my hand with medals from their dead and I will know that vengeance has been given to my fallen privateers.", completion = "Alas, the righteous Alliance guns have been silenced. You shall be rewarded for your aid, {name}.\n\nNow to tend to the grim task of recovering the bodies of the dead....", sourceObjectiveStatus = "unverified-source-field" }
quests[892] = { id = 892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Shipment", description = "Everything looks square from my records, {name}. Go on back and tell Gazlowe he's out of luck. I wouldn't be surprised if it was the pirates that nabbed his goodies.\n\nNothing else I can do for him. Oh... though you could tell him that I've got some things from Undermine for him, when he has the time to come pick them up.", sourceObjective = "Return Gazlowe's Ledger to Gazlowe in Ratchet.", progress = "So, what did Dizzywig have to say?", completion = "No dice, eh? I guess it must have been the Freebooters then... Dizzywig's on the level, I'm sure he wouldn't cheat me like that. After all, he is on the payroll.\n\nLooks like I've got some goods to get back, {name}. What do you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[893] = { id = 893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Choice", description = "The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons. I'd like to get my hands on a few different types to learn their techniques if possible.\n\nIf you wish to help bring honor to the Horde, then bring me examples of their weapons. Find me a dagger from their stalkers, a wand from their seers, and a shield from their warfrenzy. That should do nicely!", sourceObjective = "Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.", progress = "I, too, have doubts that the pathetic quilboars could attain any level of skill in the area of smithing, but I do as the Warchief commands, and I shall learn what I can about the Razormane tribe.\n\nI have had more menial tasks, and I do so willingly if it aids the orc people.", completion = "Excellent, excellent specimens indeed.\n\nThe quilboar are further along than I had expected.\n\nHere, {class}, take this and get out of my way. I'd better take a closer look at these weapons. We may have underestimated our enemy, and that's the kind of mistake we can't afford to make.", sourceObjectiveStatus = "unverified-source-field" }
quests[894] = { id = 894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange", description = "The Venture Company set up a small research facility far to the north of here, southwest of the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.", sourceObjective = "Access the control console at the Venture Company research site.\n\nProvided item:", completion = "A variety of buttons, levers and blinking lights are somewhat erratically arrayed on the face of the control console. A small gauge indicates that the apparatus is currently operating within optimal levels, and indicates that control valves one through three are currently open. There is a small keyhole set into the lower right side of the control panel.", sourceObjectiveStatus = "unverified-source-field" }
quests[895] = { id = 895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Baron Longshore", description = "WANTED!\n\nBaron Longshore, Captain of the Heedless\n\nCaptain Longshore of Gilneas leads vessels of the Southsea Freebooters, and is WANTED on charges of piracy. Remains must be in identifiable condition!\n\n-- Gazlowe", sourceObjective = "Bring the head of Baron Longshore to Gazlowe in Ratchet.", progress = "What's happening? Something I can help you with? Goods to ship, perhaps an engineering job?", completion = "Ahhhh! That sort of business. You know, I saw the Heedless once on the open seas. Fearsome ship, or was that boat... those sailors are so particular!\n\nAnyways, watching her glide across the water was quite a sight to see. I'm glad her infamous captain will trouble my ships no longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[896] = { id = 896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miner's Fortune", description = "Being Wharfmaster of a busy port like Ratchet, I keep my finger on the pulse of information. I know all about the exchange of goods and money between here and Booty Bay.\n\nThe latest bit of news I've heard is about the Venture Company's Boulder Lode mine northeast of the Sludge Fen. One of the miners discovered an emerald the size of your fist. I know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale.", sourceObjective = "Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet.", progress = "If only we knew which one of the miners had found the emerald, it'd be a walk in the park...", completion = "Look at the size of that thing, {name}! We're going to be rich! Let's see, according to the rates I've seen on gems going into Undermine, I should be able to figure out your cut--fifty percent, don't worry!\n\nNow let's see... I think this should do about right. Pleasure doing business with you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[897] = { id = 897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harvester", description = "This strange, insect-like creature looks outside of the natural order, as though it does not belong in the Barrens.", sourceObjective = "Bring the Harvester's Head to Jorn Skyseer.", progress = "You seemed troubled, {name}.  How go your lessons in the Barrens?  Did you find something that disturbs you?", completion = "I can tell nothing of the nature of this beast, for its spirit has fled.  But as you guessed, it does not belong in the Barrens.  I fear it may herald a grim future for our people...\n\nBut for now, prepare yourself, and let us hope that time unravels the mystery of this creature.", sourceObjectiveStatus = "unverified-source-field" }
quests[898] = { id = 898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free From the Hold", description = "Finally! Someone to rescue me!\n\nI can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor. I was called an enemy and threat to the Alliance.\n\nMe! A threat to their great sham of an Alliance? I was a deckhand on a moonshine transport between Ratchet and Booty Bay.\n\nEnough talk. Help me get back to Ratchet will you? Let me know when you're ready and we'll make our break.", sourceObjective = "Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet.", progress = "Yes?", completion = "And to think, we thought Firebough was long dead!\n\nYour heroics have earned you a place of honor with the Thalo'dan Privateers, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[899] = { id = 899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consumed by Hatred", description = "Perhaps you know the pain of uncertainty, perhaps not, {class}. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. Perhaps instead of heading north to the Crossroads I should have headed to Taurajo.\n\nYou, {class}--you  could help me.\n\nKill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.", sourceObjective = "Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads.", progress = "The quilboar will pay for this, {name}. I swear it.", completion = "{class}, you take my task seriously, and for that I thank you.\n\nAlthough my desire for revenge remains, I can at least smile seeing that the quilboars have felt pain themselves.", sourceObjectiveStatus = "unverified-source-field" }
quests[900] = { id = 900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange", description = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.", sourceObjective = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.", progress = "Blinking lights on the control console indicate that the main control valves have not been closed off.", completion = "The lights indicating the three control valves dim as they are shut off. Green lights slowly fade into yellow, and the switch controlling the apparatus is now moveable, with the valves closed, it can be turned off.", sourceObjectiveStatus = "unverified-source-field" }
quests[901] = { id = 901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange", description = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.", sourceObjective = "Get the Console Key from Tinkerer Sniggles to use on the control console.", progress = "The console lights are dimmed and the gauges and dials all read at their zero positions, everything idling.", completion = "Turning the key in the lock, the control console unlocks. A red light at the top of the console turns off and all power drains from the terminal.", sourceObjectiveStatus = "unverified-source-field" }
quests[902] = { id = 902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange", description = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.", sourceObjective = "Return the Samophlange to Sputtervalve in Ratchet.", progress = "Oh, you're back, {name}! Do you have the samophlange?", completion = "This is... er... interesting... yes. I'll have it sent along to the Tinkers' Union headquarters in Undermine. I'm sure after some careful dissection and research, they'll be able to make some sense of it.\n\nBut, perhaps I'll have a little look myself first...", sourceObjectiveStatus = "unverified-source-field" }
quests[903] = { id = 903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prowlers of the Barrens", description = "Now it's time to go after something that really bites.  The prowlers of the Barrens are a tough breed.  Tough, resourceful, sly... and deadly.  You'll find them among the tall grasses.  You'll find many to the southwest of the Crossroads.\n\nBe wary as you hunt them, {name}, or you may find yourself no longer the predator, but instead the prey.", sourceObjective = "Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads.", progress = "How goes your hunt, {name}?  Have you found the prowlers?", completion = "Ah, I see you've been busy, lurking in the grasses and hunting prowlers.  Do you think, then, it is time to face a champion among them?", sourceObjectiveStatus = "unverified-source-field" }
quests[905] = { id = 905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Angry Scytheclaws", description = "Now, {name}, the hunt deepens.  Now you must defeat your prey, and then find your way to its lair.\n\nHunt the sunscale raptors to the south.  Slay them and remove the feathers they wear.  Place the feathers on the scytheclaw nests southwest of the Stagnant Oasis. Show their brethren you do not fear them!", sourceObjective = "Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads.", progress = "Have you been to the nests, {name}?", completion = "So you've been to the nests and placed the feathers of your prey within them.  That took a fair portion of courage, no doubt about it.\n\nDo you feel a little tougher, {name}?  Because you look tougher now then when you first came here.  I guess the Barrens is doing its job.", sourceObjectiveStatus = "unverified-source-field" }
quests[906] = { id = 906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal from Within", description = "Take Lok's head to Thork in the Crossroads, {race}. <snort> He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in <snort> such things. But I am sure he'll reward you for carrying out such a great deed. <snort>\n\nI will continue to bless you with Agamaggan's power for as long as I remain in this cage, {race}. Until then, farewell.", sourceObjective = "Bring Lok's Skull to Thork at the Crossroads in the Barrens.", progress = "Yes, what is it?", completion = "You found the Razormane leader and killed him yourself, {name}? Amazing.\n\nI am without words, but that does not mean I am without thanks. The people of the Crossroads would do well to respect your strength.\n\nI must admit, I thought the leader of these raids on our supply lines was another quilboar. Thank you again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[907] = { id = 907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Thunder Lizards", description = "Now, {name}, you must face the great thunder lizards.  So large are the beasts, the ground rumbles as they stomp across the plains.  Take care as you fight them, for one false step and you may find yourself beneath their feet.\n\nYou will find the thunder lizards in the southern Barrens.  They are known as Stormsnouts, Stormhides and Thunderheads.  Return to me after you have bested them.", sourceObjective = "Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo.", progress = "Are the thunder lizards defeated, {name}?", completion = "It is good to see you return with proof of victory.  And it is good to know you have done so with your bones unbroken.", sourceObjectiveStatus = "unverified-source-field" }
quests[908] = { id = 908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\n{name}, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!", sourceObjective = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[909] = { id = 909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aquanis", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.You will be able to choose one of these rewards:", sourceObjective = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[910] = { id = 910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down at the Docks", description = "I have heard tales of the mighty ships that sail between Ratchet and Booty Bay!  That would be so cool to sail on the ocean and fight in many great sea battles.  Maybe I will be a mighty Horde sailor when I grow up!  Yeah!\n\nWould you take me to see the Ratchet docks, please?  I promise I won't get into the water or cause any trouble - I just want to see the big boats and smell the salty sea water!  Yeah!", sourceObjective = "Take your ward to the docks of Ratchet in the Barrens.", completion = "Wow, the ocean is HUGE!  There were a lot of seagulls and stuff too - It's just as noisy and as bustling as I thought it would be.  There are pirates near by too - so cool!\n\nThank you for taking me to Ratchet, {name}.  That was so awesome!", sourceObjectiveStatus = "unverified-source-field" }
quests[911] = { id = 911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gateway to the Frontier", description = "They say that Ashenvale is the new frontier, and that the Mor'shan Rampart in the Barrens is the gateway to it.  That would be so cool to be a pioneer, carving everything you need out of the untamed wilds!  They say that this is where the Horde and Alliance will clash the most in the future, and I want to be there {name}!\n\nWould you take me to the Mor'shan Rampart so I can see what the frontier looks like, please?  I wanna see where the Horde is driving out those smelly night elves!", sourceObjective = "Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale.", progress = "Are we there yet?", completion = "Wow, Ashenvale is where real adventure happens!  Have you ever fought in Ashenvale, {name}?  When I become a hero when I grow up, I wanna come to Ashenvale and fight for the glory Horde!\n\nThank you for taking me to the frontier, {name}.  You're the best!", sourceObjectiveStatus = "unverified-source-field" }
quests[912] = { id = 912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonesplinter Trogg Disguise" }
quests[913] = { id = 913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry of the Thunderhawk", description = "The thunderhawk, {name}, is a fierce beast.  It is time for you to face them.  You must find where it roams, and bring me its wings as proof of your successful hunt.\n\nDo this, and your time with me will near its end.", sourceObjective = "Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.", progress = "Is it done? Have you slain the thunderhawk?", completion = "You, like the thunderhawk, should be proud.  You have bested every foe we set you before, and have done so with strength, courage and honor.\n\nBut your path, {name}, continues.  In fact, you will find that true hunters forever strive, forever walk their path with the same pride you have shown me.\n\nNow, it is time to move on.", sourceObjectiveStatus = "unverified-source-field" }
quests[914] = { id = 914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaders of the Fang", description = "The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.\n\nThe Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace.\n\nGo, {name}.  You will find them lurking deep within the Wailing Caverns.", sourceObjective = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.", progress = "Memories of my nightmares haunt me, {name}.  Have you defeated the leaders of the fang and acquired their gems?", completion = "You have done it, {name}.  You killed the leaders of the Druids of the Fang.  My dreams are now free of their wicked faces, and you have helped save the Barrens from a cursed future.\n\nI thank you, {name}.  I thank you for myself, for the druids of Thunder Bluff, and for the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[915] = { id = 915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Scream, I Scream...", description = "ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world!\n\nI had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule's Strawberry Ice Cream on top??!?!", sourceObjective = "Get some Strawberry Ice Cream for your ward. The lad seems to prefer Tigule's brand ice cream.", progress = "I wish they'd make more flavors of ice cream other than strawberry, but I guess I'm lucky that strawberry is my favorite!", completion = "Mmmmmmmmm!  I love their strawberry ice cream!  If there's one thing Tigule and Foror know to do, it's make ice cream!\n\nThank you very much {name} - this is the best treat ever!", sourceObjectiveStatus = "unverified-source-field" }
quests[916] = { id = 916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Webwood Venom", description = "I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave.  They are cousin to a much smaller variety of spider; I believe the world tree has had a profound effect on them, and I would like specimens to study to confirm this.\n\nFirst, I would like some of their venom.  Gather Webwood venom sacs from the spiders in and around the Shadowthread Cave, to the north.  I can then examine them for similarities with their smaller cousin's venom.", sourceObjective = "Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil.", progress = "Did you gather the venom sacs, {name}?", completion = "Thank you, {name}.  When I return to Darnassus I will compare the venom within these sacs with the venom of other spiders.  It is my belief that it will have properties linked to the recent growth of our new world tree.", sourceObjectiveStatus = "unverified-source-field" }
quests[917] = { id = 917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Webwood Egg", description = "Now that I have the spiders' venom, I'd like some live specimens to study.  Unfortunately, capturing a living, giant spider is more than I can ask of you, young {class}.  And a giant spider is more than I could handle myself!\n\nBut if you can find an unhatched egg, then delivering specimens will be much easier, and I can then arrange for the unhatched spiders to be contained.\n\nThere must be a nest deep in the Shadowthread Cave.  Please, search for an egg in the nest and return it to me.", sourceObjective = "Bring a Webwood Egg to Gilshalan in Aldrassil.", progress = "Have you been inside the Shadowthread Cave, {name}?  Did you find a spider egg?", completion = "Ah, very good.  I will have this egg and the venom transported to Darnassus, then return there when my studies are done here.  I expect to find out a great deal from these specimens, {name}.  You have been a great help to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[918] = { id = 918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timberling Seeds", description = "The timberlings of Teldrassil are elementals of nature.  In some ways they reflect the natural order of plants and animals on our great tree.\n\nSo it is disturbing to see how angry the timberlings have become.\n\nI believe it has something to do with the soil.  I have been working on different methods of nurturing plants and would like to try them on timberling seeds.  Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?", sourceObjective = "Bring 8 Timberling Seeds to Denelan at Lake Al'Ameth.", progress = "Do you have the seeds?  I am eager to plant them.", completion = "You got them.  This is good!\n\nI will plant these seeds in special soil I have prepared.  I believe the seeds will sprout into timberlings who are much more docile.  Perhaps later you can see the results!", sourceObjectiveStatus = "unverified-source-field" }
quests[919] = { id = 919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timberling Sprouts", description = "Small timberlings are sprouting around the waters of Lake Al'Ameth.  I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble.\n\nWhen you're wandering the lake, if you see any timberling sprouts please take them.  Help keep our land clean!", sourceObjective = "Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth.", progress = "Hello, {name}.  Have you found any sprouts near the waters?", completion = "That's a lot!  I'm afraid they're spreading at a dangerous rate.  I hope I can solve the riddle of what is tainting them.\n\nThank you for your help, {name}.  The land is a cleaner place from your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[920] = { id = 920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenaron's Summons", description = "{name}, is it? I heard that Tenaron has been asking for you. You'll find him in the highest room atop Aldrassil.\n\nWe may live long lives, but it's best you not keep him waiting too long.", sourceObjective = "Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen.", completion = "Ah, {name}. I was hoping you'd be prompt in answering my summons. I have an important task that I would like you to perform.", sourceObjectiveStatus = "unverified-source-field" }
quests[921] = { id = 921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of the Earth", description = "It is time for you to set out to seek your destiny, {name}. But before you are ready to set out into the world beyond our enchanted forests, there is much you must learn about our recent history.\n\nMuch has changed with our people since the Battle of Mount Hyjal. Nordrassil lies a pale shadow of what it once was, its power used to defeat Archimonde and drive back the Burning Legion...\n\nThere is a task you must perform. Go to the moonwell north of Aldrassil and return me a phial of its water.", sourceObjective = "Fill the Crystal Phial and bring it back to Tenaron Stormgrip atop Aldrassil.", progress = "The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.\n\nThe druids take advantage of its properties, and the Sentinels revere the wells as shrines to Elune, but sorcery is forbidden to all.", completion = "So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more to be told and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[922] = { id = 922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rellian Greenspyre", description = "{name}, can you take one of the seeds you brought me to my friend, Rellian Greenspyre?  He is a druid in Darnassus, and when last we spoke he revealed his interest in my work with the Timberlings.  He had some ideas himself, and he will appreciate a specimen seed to work with.\n\nThank you, {name}.  You have been a great help to me.  I hope that, some day, you will see the fruit of my labors.\n\nYou will usually find Rellian walking the pathways of the Cenarion Enclave in Darnassus.", sourceObjective = "Bring a Timberling Seed to Rellian Greenspyre in Darnassus.", progress = "Hello...\n\nAnd how may I help you?", completion = "Ah, a timberling seed?  I wanted to try growing one of these to help Denalan with his studies.\n\nBut I'm afraid I've discovered that a corruption has grown in many of the timberlings, and seeds from such creatures carry their parent's taint.  They are beyond my talents to repair.\n\nDenalan is very skilled with things that grow.  He may find a cure for future timberlings.  He may be their only hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[923] = { id = 923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tumors", description = "There is a malevolence growing in the timberlings.  We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help.  Those that wander Wellspring Lake in northern Teldrassil are the most tainted.  They must be removed!\n\nDestroy the Timberlings you find there, and gather the mossy tumors growing upon them.  Bring the tumors to me so that they may be burned.", sourceObjective = "Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus.", progress = "Have you been to Wellspring Lake, {name}?  Have you been hunting the timberlings there?", completion = "Well done!  These tumors are the symptom of the timberling's disease.  They are filled with a poison that we must cleanse from our new land.\n\nI will dispose of these tumors.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[924] = { id = 924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon Seed", description = "The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire.\n\nI have prepared power stones that when placed near the Seed will disrupt its connection to the Legion.\n\nTake a stone from the table and bring it to the altar of fire atop Dreadmist Peak. Travel west, then north when the road forks. The Peak will be to your left. The safest climb to the top is on its northern face.\n\nAnd hurry--the stone's power will consume itself in time.", sourceObjective = "Grab a Flawed Power Stone. Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.", progress = "The Demon Seed still exists.  I can sense its power...", completion = "Your task is complete.  You have destroyed the Demon Seed as Neeru bid.  But this is not the end...\n\nThe destruction of the Demon Seed sent waves of power through the ether, waves of staggering force.  I felt them, and I am sure other beings did as well.  Others who will wonder why their toy was broken...\n\nBut regardless of future troubles, I have something for you.  Neeru sent it as payment.  And he bid me thank you.\n\nSo, thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[925] = { id = 925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cairne's Hoofprint", description = "They say that Cairne Bloodhoof is one of the greatest heroes the Horde has ever seen.  When I grow up, I wanna be a hero of the Horde too!\n\nDo you know Cairne, {name}?  Could you do me a favor, please?  Could you get his hoofprint for me?  I dunno how to ask him, and he'd probably be too busy for someone like me... but you!  You're an adventurer just like he is!  I bet he'd give you his hoofprint easy!\n\nPlease?", sourceObjective = "Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward.", progress = "When the orcs were alone and without friends, the tauren welcomed them to a strange land and shared with them without asking anything in return.  That's honor, {name}.", completion = "WOW!  You got Cairne's hoofprint for me!  Thank you very much!  And wow... he wrote a personal message on here - to me!  I knew he'd be totally cool, I just did!  Maybe someday I'll thank him myself... when I become a hero of the Horde!\n\nYou're the best, {name}.  Thank you for being so nice to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[926] = { id = 926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flawed Power Stone", sourceObjective = "These stones are infused with magical energy, but purposefully flawed.  They are very unstable and once removed from the table they will consume themselves quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[927] = { id = 927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Moss-twined Heart", description = "The heart of Blackmoss the Fetid is covered with a dark, oily moss.  In fact, the only way to tell this is a heart is from its slow, rhythmic beat... A beat that continues even now.\n\nPerhaps Denalan will want to see this heart.", sourceObjective = "Bring the Moss-twined Heart to Denalan at Lake Al'Ameth.", progress = "{name}!  You have something for me?", completion = "...What is this?  A timberling heart??  It's covered with a foul moss!\n\nThank you for bringing this to me, {name}.  I will examine the heart and, if fortune shines, determine the nature of the moss about it.", sourceObjectiveStatus = "unverified-source-field" }
quests[928] = { id = 928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of the Earth", description = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, {name}. There are dangerous beasts in the forests of late.", sourceObjective = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.", progress = "Greetings, {class}. For what purpose do I owe the pleasure of our meeting?", completion = "Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do, and little time to do it in.\n\nI think we'd best get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[929] = { id = 929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of the Earth", description = "First, let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells.\n\nTake this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. When you have completed your task, I shall continue the story where Tenaron left off...", sourceObjective = "Fill the Jade Phial and bring it back to Corithras Moonrage in Dolanaar.", progress = "Hello again, {name}. Have you completed your task?", completion = "After the Battle of Mount Hyjal, we were without direction. Nordrassil smoked from the fire it unleashed, and our immortality--the very essence of our beings!--was lost.\n\nIt was in this trying time that the Betrayer was freed from his prison, and Shan'do Stormrage disappeared. A dark time for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[930] = { id = 930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glowing Fruit", description = "Hanging from beneath its fronds of this glowing plant is a large, round fruit.\n\nDenalan would want to study this fruit, you are certain.", sourceObjective = "Bring the glowing fruit to Denalan at Lake Al'Ameth.", progress = "{name}, you look like you have something to tell me.  Do you have news concerning the timberlings?", completion = "You found this on Teldrassil?  Intriguing... this fruit is exotic.  Perhaps its seeds were brought here from far off.  Perhaps even as far as Azeroth!  And there's something about this fruit... it seems to have reacted very strangely with the soil of Teldrassil.\n\nThank you, {name}.  Now if you'll excuse me, I must study this further...", sourceObjectiveStatus = "unverified-source-field" }
quests[931] = { id = 931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shimmering Frond", description = "The fronds on this plant shimmer in the forest light, giving it a twisting, pulsing aura.\n\nYou believe that Denalan would want a specimen of this.", sourceObjective = "Bring a Shimmering Frond to Denalan at Lake Al'Ameth", progress = "You have something for me?", completion = "Where did you get this?  I haven't seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago!  It's amazing that a specimen made its way to Teldrassil.  And it's grown to such a size!\n\nThank you, {name}.  Forgive my shortness of words, but there is a test I would like to perform on this frond...", sourceObjectiveStatus = "unverified-source-field" }
quests[932] = { id = 932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Hatred", description = "I must warn you, {name}, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home.\n\nHe is called Lord Melenas. He resides in the nearby cave of Fel Rock where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul.\n\nYou must find him within his nearby cave just to the north of here, and bring me his head.", sourceObjective = "Kill Lord Melenas and bring his head to Tallonkai Swiftroot in Dolanaar.", progress = "Did you kill Lord Melenas yet? It is vital that he be taken care of quickly and quietly, {name}. His continued existence is an embarrassment to us all.", completion = "With Lord Melenas laid to rest I can finally move on to other matters. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[933] = { id = 933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of the Earth", description = "There is another moonwell southeast of the entrance to Darnassus, on the shores of the Pools of Arlithrien. The Sentinels are having problems patrolling the area because of attacks and the growing ill-temperedness of the Gnarlpine furbolgs.\n\nBe wary as you seek out the well, and keep your weapons close at hand.", sourceObjective = "Fill the Tourmaline Phial and bring it back to Corithras Moonrage in Dolanaar.", progress = "At first the reports of crazed furbolg attacks were dismissed. Who could have thought that the peace-loving bear-men would turn to mindless rage? Yet another of the problems that plagues us here in our new home.", completion = "Shan'do Stormrage never returned, and the druids were in disarray, and to this day we still do not know what became of him. With Malfurion missing, Arch Druid Fandral Staghelm took over the leadership of the druids, convincing the Circle of Ancients in Darkshore that it was time for our people to rebuild, and that it was time for our people to regain their immortality.\n\nWith the approval of the Circle, Staghelm and the most powerful druids grew Teldrassil, the new World Tree.", sourceObjectiveStatus = "unverified-source-field" }
quests[934] = { id = 934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of the Earth", description = "All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.\n\nHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.", sourceObjective = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[935] = { id = 935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of the Earth", description = "Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw. Strange beasts have been reported arising from the very ground of the tree, and crazed furbolgs attack passing travelers.\n\nI can only hope that the solution the Arch Druid is looking for will be found quickly. I will pour all the phials you brought into this vessel, for you to deliver to Darnassus.\n\nBring it to Fandral Staghelm, you will find him in the druid grove.", sourceObjective = "Bring the Filled Vessel to Arch Druid Fandral Staghelm in Darnassus.", progress = "I know that I did not summon you, so I cannot help but wonder why it is you have come to speak with me.\n\nWhatever it is, please make it quick.", completion = "Ah yes, the water I had requested. Tenaron and Corithras certainly took their time in having it delivered... perhaps not choosing the most reliable of messengers... hmm.\n\nNonetheless, I can finally get back to my work then. The weight of Teldrassil's problems fall upon my shoulders. A yoke I would wish to soon be rid of.\n\nTake this, you may find some use for it.", sourceObjectiveStatus = "unverified-source-field" }
quests[936] = { id = 936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting Arch Druid Runetotem", description = "Excuse me {class}, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", sourceObjective = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", completion = "Greetings, {class}; I am glad you are interested in assisting our research.  There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous.  Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.", sourceObjectiveStatus = "unverified-source-field" }
quests[937] = { id = 937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enchanted Glade", description = "I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back.\n\nWhen the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies.\n\nIf you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds.", sourceObjective = "Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade.", progress = "Their slashing talons and piercing beaks may prove a difficult match for your own abilities, {name}, but I have faith that you will not fail in this task.", completion = "I am impressed by what you have accomplished here in so short a time, {name}. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you.\n\nI have noticed the Oracle Tree has just shed a piece of its bark. No doubt it has a task that it wishes completed. You should speak with it.", sourceObjectiveStatus = "unverified-source-field" }
quests[938] = { id = 938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mist", description = "The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach.\n\nShe raises her head and gazes at you, bright intelligence shining in blue eyes. She seems to wish to follow you.", sourceObjective = "Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree.", progress = "Mist... It was my fault! The witches caught me off guard... I should not have let them take you...", completion = "Oh, thank you, {name}! I feared I would never see Mist again, knowing only her death in my heart, never to be united with my faithful companion. I owe you more than you can know, and you have my eternal gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[939] = { id = 939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flute of Xavaric", description = "You study the simple wooden flute you picked up after defeating Xavaric.\n\nThe knotted wood feels solid, but it seems as if the spirals and patterns in the surface begin to spin and move as you turn it over in your hands. Suddenly, you feel a sense of dread...\n\nYou shake your head, sure that your mind is playing tricks on you.\n\nIt's possible that other satyrs carry clues as to what you have found. Bring your findings to the druid, Eridan Bluewind, that lives in southern Felwood.", sourceObjective = "Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood.", progress = "What is it, {class}? You look concerned.", completion = "I sense the suffering of ancient ones, {name}...\n\nHolding these items is almost unbearable...", sourceObjectiveStatus = "unverified-source-field" }
quests[940] = { id = 940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassil", description = "The forest whispers of your feats of valor, {name}. As I felt the harpies forced from their nests, a greater calm spread across the forest, its creatures once again feeling safe. I have feared sending another messenger to the Arch Druid, but I know that you will see my message safely to him.\n\nDeliver this to him and know that the forest will see you safely along its paths to the forest of stone.", sourceObjective = "Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus.", progress = "Hmm... You come with the spirit of the forest strongly within you, {class}. What business do you have with the Arch Druid of the Kaldorei?", completion = "I wondered why the Oracle Tree had not communicated with me for so long... It seems that some problems are lessened while others grow to greater concerns.\n\nI fear my work on Teldrassil shall never be completed, and our immortality never restored.\n\nNonetheless, you have done the Oracle Tree's task well, and should be rewarded for your diligence.", sourceObjectiveStatus = "unverified-source-field" }
quests[941] = { id = 941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Planting the Heart", description = "I have removed that foul moss from the heart, but it remains tainted...\n\nTry placing the heart in my planter.  It is filled with a nutritive soil that may cleanse and heal the heart.", sourceObjective = "Plant the Tainted Heart in Denalan's Planter.", progress = "This planter is filled with soil, specially prepared by Denalan.", completion = "You place the heart within the planter, and it quickly digs itself in!\n\nA few seconds later it wriggles back out, cleansed.  It pulses slightly... beckoning for you to take it.", sourceObjectiveStatus = "unverified-source-field" }
quests[942] = { id = 942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absent Minded Prospector", description = "This fossil bears a striking resemblance to one I once saw in Ironforge. An archaeologist by the name of Flagongut brought it to our annual Explorers' League conference. He believed the fossil had a power which could be unlocked somehow.\n\nLast I heard Flagongut had holed up in the Deepwater Tavern in Menethil Harbor, awaiting escort to the Whelgar Excavation Site. Seek him out and show him Remtravel's fossil. Perhaps he can reveal the secrets of the past.\n\nGood luck findin' your way there!", sourceObjective = "Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor.", progress = "What ya got there, friend?", completion = "Oh my! You say this came from the distant lands of Kalimdor?\n\nAmazing! Simply amazing!", sourceObjectiveStatus = "unverified-source-field" }
quests[943] = { id = 943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Absent Minded Prospector", description = "Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil.\n\nWhile I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost. I don't know which one of the mottled beasts swallowed the relic but if you can retrieve it, I can unleash the power of these artifacts.\n\nBring me both the Stone of Relu, and the original fossil he holds.", sourceObjective = "Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.", progress = "With the Stone of Relu I will be able to release the hidden secrets of my fossil as well as Remtravel's fossil from Darkshore, {name}.", completion = "Most excellent, {name}!\n\nNow to see if I can use the stone to decipher the powers of the fossils.", sourceObjectiveStatus = "unverified-source-field" }
quests[944] = { id = 944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Glaive", description = "It is strange that the naga are here, in Darkshore.  But stranger still...are the Twilight's Hammer.  That cult worships the old, old lords of the earth.  Lords defeated long ago.\n\nThe Master's Glaive, to the south, is a place where such an old lord fell.\n\nGo there and look for more Twilight's Hammer cultists.\n\nTake this phial of scrying.  Use it to create a scrying bowl after searching the Master's Glaive.  Then speak to me through the bowl.", sourceObjective = "Gather information, then use the Phial of Scrying to create a Scrying Bowl. Use the bowl to speak with Onu.", progress = "The Master's Glaive, {name}.\n\nGo there, then speak with me again.", completion = "The Twilight's Hammer is at the Master's Glaive?\n\nUnfortunate.\n\nThe old lord impaled by the glaive is long dead, but that does not mean slivers of his power do not still remain.\n\nThe Twilight's Hammer must be seeking this power.", sourceObjectiveStatus = "unverified-source-field" }
quests[945] = { id = 945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therylune's Escape", description = "Help!\n\nI was wandering around the Master's Glaive, and these dirty cultists surrounded me.  Lucky I'm good at hiding!!\n\nCan you help me out of here?  And I need to send word to my sister Therysil that I'm all right.  She's in Ashenvale to the south, at the Shrine of Aessina.", sourceObjective = "Help Therylune escape, then tell Therysil at the Shrine of Aessina in Ashenvale that her sister is safe.", completion = "My sister was where??  Therylune doesn't mind getting herself dirty, but still!  That's a long way to wander, and the Master's Glaive is an unwholesome place...\n\nWell thank you, {name}.  It was very nice of you to let me know she's all right.", sourceObjectiveStatus = "unverified-source-field" }
quests[947] = { id = 947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cave Mushrooms", description = "I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave.  The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains.\n\nI would go there myself, but I was advised by the Grove of the Ancients to stay away from that place.  Our venerable allies sense that the cave is the hiding place for a new evil in Darkshore.\n\nPlease, {name}, gather the mushrooms for me.  And while doing so, scout the cave to confirm the Ancients' fears.", sourceObjective = "Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine.", progress = "Do you have my mushrooms, {name}?  Have you been to the cave?", completion = "Many thanks, {name}.  These mushrooms are fine specimens!\n\nAnd when you were at Cliffspring Falls, did you find anything to confirm the warnings of the Ancients?\n\nThe Ancients are wise, but I had hoped that, this time, they were wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[948] = { id = 948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onu", description = "Onu, an Ancient of Lore at the Grove of the Ancients, knows of your journey to Cliffwater Falls and wishes to speak with you.  The grove lies to the south, nestled near the mountains.\n\nThe Ancients are patient and wise, {name}.  But if Onu seeks your counsel concerning what you saw in the falls, then I fear it is urgent.", sourceObjective = "Speak with Onu at the Grove of the Ancients.", completion = "{name}.  You are here.\n\nGood.\n\nWe have matters...to discuss.  You and I.", sourceObjectiveStatus = "unverified-source-field" }
quests[949] = { id = 949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Camp", description = "The Twilight's Hammer's purpose at the Master's Glaive is not known.  But it must be dark.\n\nSearch through their camp at the Glaive... Search for some thing that may teach us their intentions.\n\nFor we must learn their intentions before a plan is made.", sourceObjective = "Find a clue in the Twilight's Hammer camp at the Master's Glaive.", completion = "This book is hand printed in an ancient language, and illustrated by a master artist.", sourceObjectiveStatus = "unverified-source-field" }
quests[950] = { id = 950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Onu", description = "Peering into the Twilight Tome is maddening.  Text begins to swim and dance after only a moment's glance, and once beautiful scrollwork twists into grotesque shapes.\n\nTearing away one page of insane scribbles is all that is possible before a swoon overtakes you.", sourceObjective = "Bring Onu the recovered Insane Scribbles.", progress = "{name}.  You return.", completion = "A chaotic, primal magic surrounds this parchment of scribbles.  I sense the work of the old ones in it.\n\nLet us hope it reveals the purpose of the Twilight's Hammer in Darkshore...", sourceObjectiveStatus = "unverified-source-field" }
quests[951] = { id = 951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathystra Relics", description = "The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!  It is heavily cursed and tainted by the corruption of the Twilight's Hammer, but it seems the cult is using ancient elven magic to bring their old masters back to our world.\n\nTravel to the ruins of Mathystra to the northeast, and search for ancient relics among the grass and broken stones.  Through their study, we may divine how the Twilight's Hammer intends to exploit the magic of the elves.", sourceObjective = "Bring 6 Mathystra Relics to Onu at the Grove of the Ancients.", progress = "{name}.  Has your rooting through the Ruins of Mathystra been fruitful?", completion = "Thank you.  These relics are from a time when Mathystra shone.  That once great bastion of the elves has faded, but shards of its magic remain.  Let us hope we can unlock the secrets of that place before our enemies...\n\nBe vigilant, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[952] = { id = 952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grove of the Ancients", description = "If you had enough time to run messages for the Oracle Tree, then I'm sure that I can press you into service to deliver a message to the Grove of the Ancients in Darkshore, due south of Auberdine.\n\nYou will most likely have to secure transport on a hippogryph, but I have faith enough in you that you can manage that. Take this to Onu, the Ancient of Lore. He has been awaiting word from me, even as I waited for news from the Oracle Glade.", sourceObjective = "Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine.", progress = "Ah. {class}. How may Onu assist you?", completion = "Ah. Thank you, {name}. It is strange, though. The Arch Druid always seems in such a hurry. The forest knows that all shall come to pass in the appointed time. Shan'do Stormrage understood that.", sourceObjectiveStatus = "unverified-source-field" }
quests[953] = { id = 953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Ameth'Aran", description = "To the east you will find the ruins of Ameth'Aran. It is now inhabited by the restless spirits of the Highborne that once dwelt within its walls, but once it was a place where the servants of Azshara freely practiced their powerful magics.\n\nI was sent to explore the ruins and came across two large tablets, scrawled with the stories of Ameth'Aran and its fall. While I read the runes, I was accosted by the spirits, and fled.\n\nPlease, if you can, venture to the ruins and decipher the tablets in my place.", sourceObjective = "Study the tablets which tell of Ameth'Aran and of its fall, then return to Sentinel Tysha Moonblade in Darkshore.", progress = "When you have studied the tablets and learned of Ameth'Aran's fall, I will take the knowledge on to Auberdine, and inform the Circle of Ancients.", completion = "We have few records from the time around the War of the Ancients, especially near the destruction of the Well of Eternity. Given the upheaval and cataclysmic events that were taking place, it is no big surprise.\n\nThank you, {name}. With your help, my work here is finished, and I will be able to deliver a full report to the Circle.", sourceObjectiveStatus = "unverified-source-field" }
quests[954] = { id = 954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bashal'Aran", description = "The ruins of Bashal'Aran to the east are overrun with demonic minions. The sprites and satyrs that have taken up residence in the area feed upon the magical energies of the area, their powers growing from continued exposure.\n\nEven with that, I have noticed that there is one shrine they will not approach. On the western side of the ruins, atop a small bluff, a strange blue aura permeates... There must be an explanation to the demons' reluctance.\n\nI would like you to investigate it.", sourceObjective = "Find the source of the strange blue aura in the ruins of Bashal'Aran.", completion = "Ahh... To what could I possibly owe the exceedingly special honor of a {race} such as yourself as company. Truly it says much of my current companions--with no offense to my hosts, the noble grells and satyrs--that your presence could be considered an improvement.\n\nBut please, do not let my uncivil tongue drive you from the place. It has indeed been many years, decades even, since I had civil accompaniment.", sourceObjectiveStatus = "unverified-source-field" }
quests[955] = { id = 955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bashal'Aran", description = "If I were to relate the story of my life, I have no doubt it would surpass the limits of your patience. Let us say that mine has been a long and painful life, and this spectral form is perhaps the worst torment of all.\n\nI am held here by the means of magic. Though my words may seem disingenuous, I assure you I would be grateful beyond words if you would help me find the means of my imprisonment. A seal binds me, and by examining the earpieces of the sprites and grells, I may find a trace of it.", sourceObjective = "Acquire 8 Grell Earrings for Asterion in Bashal'Aran.", progress = "Once I have the earrings, I will cast the spell to search for the whereabouts of the seal that binds me. For centuries I have thought on the freedom destroying the seal would bring to me... Perhaps those centuries have taken a toll upon my mind that I might never recover...", completion = "Indeed... The grells of Bashal'Aran do not possess that which I am searching... however they have come into contact with it recently. Recently... I would reckon that by your time, not mine. Recent for me stretches into the veil of the past, almost another Age...", sourceObjectiveStatus = "unverified-source-field" }
quests[956] = { id = 956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bashal'Aran", description = "If the grells have come into close contact with the seal that binds my eternal prison, I suspect I know the cause. No doubt the seal has come into the possession of the satyr that lead them.\n\nI feel strongly that this must be true, {name}. One of the satyr must surely possess it. If you can obtain it, you would bring me so close to passing the bars of my prison that tears would come to my eyes.", sourceObjective = "Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran.", progress = "The pillars of this shrine are as the bars of a prison to me, {name}. No strength I still possess might break them, and no magic I wield might destroy them...\n\nFor a thousand years and more I have stared at them, wondering if at long last I outlived even the stone, would I be free? Or would it be invisible bars that held me then...", completion = "It... it is hard for me to even believe that what I hold now is that which has held me for so long. Let us waste no time, {name}. When the seal is destroyed, I might walk the forests of the earth freely again.", sourceObjectiveStatus = "unverified-source-field" }
quests[957] = { id = 957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bashal'Aran", description = "It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color. In this flame this seal could be destroyed.\n\nBe wary in the ruins, {name}...", sourceObjective = "Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.", progress = "In truth, {name}, I am afraid... Afraid that your coming--all of this--is merely a figment of a deranged mind. Can you know the torture that this is? I... Please, you must go quickly.", completion = "I am freed, {name}! I can now see with my own eyes the changes that have come to our world... Only bits and pieces have I known. To think that when I last walked freely, the Well still stood and the Highborne held court with Azshara, our beloved queen.\n\nI sense that my jailor, my former master, Athrikus, still lives... Already my feelings of hopelessness will give way into thoughts of vengeance.", sourceObjectiveStatus = "unverified-source-field" }
quests[958] = { id = 958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of the Highborne", description = "{class}. A task I would ask of you.\n\nHave you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south. Once they were the home of many powerful Highborne, now they are a testament to the destruction their dabblings produced.\n\nI have been told by the Sentinels that the spirits of the Highborne persist, and that they wield their ancient magical implements. Those relics must be appropriated, so that we might destroy them.", sourceObjective = "Retrieve 7 Highborne Relics for Thundris Windweaver in Auberdine.", progress = "If only the tools of their undoing could have been destroyed in the cataclysm that destroyed our world... Nonetheless, we must do what we can to ensure that the horrors of our past are not repeated in the future.", completion = "Though it is surely a figment of my imagination, I feel as though I can almost feel the taint of foul Highborne magic upon them. I will have these destroyed, so that their long dormant evil might never be released again.", sourceObjectiveStatus = "unverified-source-field" }
quests[959] = { id = 959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Docks", description = "Oops!\n\nHad a little mishap, as you can see! The morning cargo shipment from Booty Bay was huge. Huge I say! Never seen so many crates. Well, I was trying to expedite things so I started unloading a bit more than I could handle. That's when everything came tumbling down.\n\nBefore I knew what was going on, I saw that menace, Mad Magglish, go running off with a bottle of 99-year-old port. Chased him all the way to Wailing Caverns. No way I was going in there.\n\nMaybe you're brave enough to find him?", sourceObjective = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.", progress = "The dockmaster has been on my case ever since Mad Magglish made off with that 99-year-old port. I guess that bottle was intended as a gift for Gazlowe from none other than Baron Revilgaz himself.\n\nIf you're brave enough and patient enough to seek out Mad Magglish and get that port back, I'll see to it you get a nice reward.", completion = "Superb! And just as I was about to lose my job too! I will see to it that Gazlowe gets this gift immediately.\n\nThank you, {name}. Nicely done, I say!", sourceObjectiveStatus = "unverified-source-field" }
quests[960] = { id = 960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onu is meditating", sourceObjective = "I am meditating on your task, {name}.  Meditating on reasons why the Twilight's Hammer and naga are here.\n\nWhen you are ready, use the phial of scrying to create a scrying bowl.  Then, contact me through the bowl.\n\nIf you have lost your phial of scrying, then here is another.", sourceObjectiveStatus = "unverified-source-field" }
quests[961] = { id = 961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onu is meditating", sourceObjective = "The finding of Twilight's Hammer cultists is troubling.  I must meditate on their intentions...\n\nWhen you have more information, speak to me through a scrying bowl.  If you require a phial of scrying in order to create a bowl, then...here is another.", sourceObjectiveStatus = "unverified-source-field" }
quests[962] = { id = 962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serpentbloom", description = "The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, {name}. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken.\n\nRecently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential.\n\nUnfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.", sourceObjective = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.", progress = "I am eager to see if you can gather enough Serpentbloom from the Wailing Caverns. I've sent many to do my bidding but none have returned.", completion = "Ah, splendid specimens. You have done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[963] = { id = 963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Love Eternal", description = "In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya.\n\nI would never have thought, thousands of years later, that memories of Anaya would still haunt my dreams. Wandering the woods of Darkshore in a stupor, I found myself in the ruins of Ameth'Aran... where I saw the haunted spirit of my beloved.\n\nShe must be freed, but I lack the heart to do it. Her spirit must be destroyed.", sourceObjective = "Free the spirit of Anaya Dawnrunner and bring her pendant back to Cerellean Whiteclaw in Auberdine.", progress = "With a great sorrow in my heart, I followed the Shan'do Stormrage into hibernation, and took my sorrow to my dreams, sleeping for the passing of thousands of years.", completion = "Thank you, {name}. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.\n\nPlease, I would be alone with my grief...", sourceObjectiveStatus = "unverified-source-field" }
quests[964] = { id = 964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skeletal Fragments", description = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.\n\nFirst thing's first though, {name}.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.", sourceObjective = "Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands.", progress = "Kill many and kill often, {class} - we'll need a decent supply of suitable skeletal fragments to make up the outer layer of the key.  They don't call it a Skeleton Key for nothing, you know.", completion = "This'll work, {name}!  My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.\n\nThe next step will be to get an appropriate mold for the key.  I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items.  He works for whom goblins usually work for - the highest bidder.", sourceObjectiveStatus = "unverified-source-field" }
quests[965] = { id = 965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "Hail, young {race}. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.\n\nTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.\n\nIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.", sourceObjective = "Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore.", completion = "Elissa sent you? Then it is good tidings you bring. I have troubling news to report to her, and had no means with which to deliver it.", sourceObjectiveStatus = "unverified-source-field" }
quests[966] = { id = 966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "A group of warlocks has taken up residence around and inside the tower. I would have returned to Auberdine to report to Elissa earlier, but I was afraid that I might miss something while I was away.\n\nDelgren suspected such a company might be gathering at the tower, but did not know why.\n\nA few scraps of parchment that the warlocks carry have found their way to my hands, but I need more to complete the puzzle. I warn you not to venture into the tower, however, the warlocks there are much more powerful!", sourceObjective = "Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx.", progress = "Have you found any more of their scrolls? I should be able to piece together a larger picture of the cult if you can find them.", completion = "Many thanks, {name}. This should shed some light on this warlocks' gathering...\n\nHmm... the Cult of the Dark Strand... I have never heard of this group before. Having no knowledge of their history, it is all but impossible to say what their plans must be.\n\nThere is no more time to delay. Warning must be delivered to Delgren immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[967] = { id = 967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "My master, Delgren the Purifier, is a paladin who has graciously offered his assistance in defending our forests from the forces of the demons and undead. He has taught me much about the Holy Light and the art of battle.\n\nDelgren must know of the cult's operations immediately.\n\nYou will find him far south of here at Maestra's Post in Ashenvale Forest. Be swift, I fear the Dark Strand's threat grows with each passing hour.", sourceObjective = "Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest.", progress = "You have some business with me, {class}?", completion = "If you don't mind my saying, you seem a bit well-equipped for a messenger, hm? I suppose Balthule wanted to be certain that his letter reached my hands. Let's see what he has to say...\n\nThis is disturbing news. When undead or demonic forces are found, I help the Sentinels destroy them.\n\nAt first I was unaccustomed to the manners of the night elves, but I have grown to respect them greatly as allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[968] = { id = 968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Powers Below", description = "Although terribly worn and scratched, the title of this book can still be read upon its cover:\n\nThe Powers Below\n\nInside the book is a listing of unpronounceable names with foreboding titles, methods of worship, and preferred sacrifices...many of which include living, humanoid creatures.\n\nOn the inside cover of the book are the words: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge.  Proprietor: Gerrig Bonegrip.\"\n\nIf Bonegrip sells books like this, perhaps he'll buy this one back.", sourceObjective = "Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge.", progress = "Hello, sir.\n\nMay I interest you in one of my tomes?", completion = "Ah, a copy of The Powers Below.  An interesting text, this is.  And some might find it useful...\n\nBut this one's in sad shape.  And look here!  There are notes in the margin of almost every page!\n\nHm...I know this copy.  I sold it to Bolgar last year.  Are you...a friend of his?  Yes, I thought you were.  You have that same fire behind your eyes!\n\nWell, by definition, a friend of Bolgar's is a friend of mine.  And we take care of our own, yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[969] = { id = 969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luck Be With You", description = "Ah, I can tell just by lookin' at ya -- you be wantin' to make a lucky charm. Mau'ari always knows!\n\nTo da south. you'll find a canyon, an' giants made a' solid ice. The giants sometimes be carryin' dem, but ya can always gather da shards yerself from da canyon. These shards have a powerful reflective quality.\n\nBring back 4 frostmaul shards, and my lucky charm will be yours.", sourceObjective = "Collect 4 Frostmaul Shards for Witch Doctor Mau'ari in Everlook.", progress = "Bring back da shards, and I be tellin' you more!", completion = "Ahh, yes... I will make da charm for ya now. Just you wait!", sourceObjectiveStatus = "unverified-source-field" }
quests[970] = { id = 970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "Balthule's letter is dire. This Cult of the Dark Strand is a thorn in my side that must be removed. I have been dealing with some of the Dark Strand scum northeast of here at Ordil'Aran. One of their number possesses a soul gem that I believe holds the secret to the cult's power.\n\nBring it to me, and I will be able to decipher the secrets held within.", sourceObjective = "Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.", progress = "Have you acquired that soul gem?", completion = "Hmm, some dark magic enchants this soulstone. Let's see what's trapped inside, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[971] = { id = 971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge in the Deeps", description = "As you might know, I collect lore.  Old lore.  Powerful lore.  Lore that opens doorways, and lore that can awaken Those Who Sleep.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in Ashenvale.  That place is the old dwelling of long-dead elves.  Elves who held great knowledge before their city fell to ruin.\n\nSearch Blackfathom Deeps for the manuscript.  Do this, and I will not forget it.  Not even after ... the end days.", sourceObjective = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.", progress = "The journey to Ashenvale is long, and your task is not easy.  But if you get me the manuscript, {name}...then your reward will be great.", completion = "You found the manuscript!  What a joyous day this is!  Copies will be made and distributed, and the ancient knowledge of Lorgalis will finally be known to my brothers and sisters!\n\nYour service to us is more than you know, {name}.  But I hope that this gift shows you the gratitude we extend to our allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[972] = { id = 972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Sapta", sourceObjective = "Take the water sapta and find the corrupted pool of water in Silverpine, {name}. I have great faith in your abilities.", sourceObjectiveStatus = "unverified-source-field" }
quests[973] = { id = 973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine,  a place of great evil in southwestern Ashenvale.\n\nHe had been little more than an annoyance until now, and I had not dealt with him, but it seems that his time has come.", sourceObjective = "Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.", progress = "You look a bit shaken up, {name}. Are you well?", completion = "It was a grand thing you did today, {name}. You should be quite proud of yourself for having faced down a warlock of such power.\n\nNow, let's see what we can learn from Ilkrud's writings.", sourceObjectiveStatus = "unverified-source-field" }
quests[974] = { id = 974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Source", description = "The hot springs here are a source of mystery to me. Where does the heat come from?\n\nLooking at how close the pools are to Fire Plume Ridge, I really wonder if the volcano might have something to do with it. I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest part. It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!", sourceObjective = "Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\n\nWhenever you find a hot spot, right click the thermometer to check the temperature. Keep looking until you find the hottest one.", progress = "I'd go there myself, but... I'm a little scared of the fire elementals there!", completion = "Yes, I definitely see the correlation here between the temperature of the volcano and the hot springs. I'll have to double-check my equations for accuracy, but it seems like the distance and the rate that the heat is transferred... Hmm...", sourceObjectiveStatus = "unverified-source-field" }
quests[975] = { id = 975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cache of Mau'ari", description = "Now, before I give ya dis charm, I better explain how ta use it.\n\nIf you carry da charm with ya, you'll find dat certain items will drop from creatures ya fight. If you don't have da charm with you, you won't find them. Understand?\n\nYou'll know these special items by the name -- they be called E'ko. If you find any of these items, just bring dem to ol' Mau'ari, and she help ya out.\n\nWait here while I fix your charm.", sourceObjective = "Speak to Witch Doctor Mau'ari again in a moment to receive the lucky charm.", completion = "Here it is, {name}. Remember, ya have ta carry it with you. Why don't ya head back to da wilds, an' see what ya be findin' there?", sourceObjectiveStatus = "unverified-source-field" }
quests[976] = { id = 976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies to Auberdine", description = "Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own. Dangerous foes operate in the forest, and I do not wish to risk letting these supplies and information fall into the wrong hands.\n\nIf you and others could act as my guards, I could leave now. With your protection, I have no doubt that we can see these goods safely to Auberdine.", sourceObjective = "Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.", progress = "The Sentinels have a great need for supplies to reinforce themselves in Darkshore.", completion = "You have done well today, {class}. The items we sent to aid Auberdine will be of immediate use in dealing with the dark threats that infest the forest.\n\nTake these with my heartfelt thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[977] = { id = 977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Are We There, Yeti?", description = "Now that I have what I need to cover the mechanical moving parts, I only need one other thing. Well, actually two. Two horns!\n\nThe ice thistle patriarchs and matriarchs have the largest horns, so of course, those are the ones I want. That type of yeti inhabits a cave to the southeast. There are plenty of them there; you shouldn't have any problem finding them.\n\nRemember, I only want the best looking ones -- no beat up or broken horns, please!", sourceObjective = "Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook.", progress = "I've just about finished attaching the fur, {name}. Please, hurry back with those horns!", completion = "I can't wait to show my friends! Now, just wait a moment while I attach these...\n\nPerfect!", sourceObjectiveStatus = "unverified-source-field" }
quests[978] = { id = 978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moontouched Wildkin", description = "Wildkin feathers from the Hinterlands appear to contain traces of magical qualities. These powers... they don't seem to be wielded by the creatures, it's more like they are simply inherent to the species -- part of their very essence.\n\nDuring my studies, I heard that a large population of wildkin inhabit the snowy lands of Winterspring. Could these creatures have the same powers? Please help me find an answer, {name}. Go to Winterspring and gather feathers that have dropped to the ground, then return to me.", sourceObjective = "Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village.", progress = "Where could these powers have originated from? I think we are on the right track to find the answer, {name}.", completion = "Now I can compare the feathers... Let's see...", sourceObjectiveStatus = "unverified-source-field" }
quests[979] = { id = 979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Ranshalla", description = "Yes, yes, these feathers seem to hold the same magical enchantment that I noticed previously... While I am not certain what we might find, I urge you to continue searching for answers, {name}.\n\nA colleague of mine recently traveled into Winterspring to observe the wildkin there, in their own habitat. Why don't you catch up with her and see what she has found?", sourceObjective = "Find Ranshalla in eastern Winterspring.", completion = "Hi! Erelas sent you? Great, I was just preparing to travel up to the caves now, and I wouldn't mind company.", sourceObjectiveStatus = "unverified-source-field" }
quests[980] = { id = 980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Springs", description = "Now, I've heard about other hot springs in a place called Winterspring, far to the north of here. The strange thing is, there are no volcanoes anywhere near them. Interesting, I know.\n\nWell, if you want to find out more, you should head to Winterspring and speak to a friend of mine. Her name is Donova Snowden, and she is currently staying by the hot springs there.\n\nThanks again for helping me with my thermometer! See you later!", sourceObjective = "Travel to Winterspring and speak with Donova Snowden.", completion = "Hi there, {name}. Yes, what Krakle told you is true...", sourceObjectiveStatus = "unverified-source-field" }
quests[981] = { id = 981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tower of Althalaxx", description = "For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered.", sourceObjective = "Talk to Delgren the Purifier at Maestra's Post.", completion = "I knew you would be up to the task, {name}.\n\nI sense great deeds before you, and that you will right many of the wrongs that plague our lands. Bear my blessings, {name}, as well as this gift.", sourceObjectiveStatus = "unverified-source-field" }
quests[982] = { id = 982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Ocean, Vast Sea", description = "Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil.  Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine.  They now lie at the bottom of the ocean as trophies for those fiends.\n\nBoth captains didn't make it out that night, and their logs and other effects are still below in lockboxes.  I'd like for you to recover them for us; it would mean a lot to the crew members still around these parts.", sourceObjective = "Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine. Both items should be found aboard the wreckage of the ships to the north of the village.", progress = "The captains of those ships were good night elves, and they deserve a better fate than they were given.  Perhaps tending to their personal effects will be the best way to put their spirits to rest.", completion = "You've done us here in Auberdine a great service, lad.  We'll make sure that their effects are properly taken care of.\n\nAs for you, please have this.  It is the least I can do for someone with the bravery to set things right.", sourceObjectiveStatus = "unverified-source-field" }
quests[983] = { id = 983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzbox 827", description = "Hey! Help me with my latest invention, the buzzbox. You can talk to people far away!\n\nMaybe you've already seen them, they're boxes with levers on them. The only problem is they need constant maintenance.\n\nEach one suffers from a different problem, but I made a really smart decision. I placed each one near creatures that have the proper parts to fix that particular machine. Right now Buzzbox 827 is on the fritz. It's just south of Auberdine, real close. It takes 6 Crawler Legs to fix it. I'll pay ya...", sourceObjective = "Collect 6 Crawler Legs and place them in Buzzbox 827.", progress = "Buzzbox 827 sits with an eerie silence. A single flashing light indicates that it needs 6 Crawler Legs to be placed in its holding box.", completion = "As you place the Crawler Legs inside the machine, you hear gears begin to grind. Judging from the banging sounds coming from the Buzzbox, you believe the Crawler Legs are being put in their proper place. Soon the machine begins to hum, and you hear a tiny voice calling out from within.\n\n\"Hello? Uhh... Hello! You fixed it! This is Wizbang by the way! Thanks a lot... Hey, you wouldn't want to fix another one, would ya?\"", sourceObjectiveStatus = "unverified-source-field" }
quests[984] = { id = 984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Big a Threat?", description = "Some of my brethren were rescued from a corrupt furbolg in Teldrassil, and I've vowed to stop any more atrocities before more of our kind are injured... or worse.\n\nI have seen a couple hints of corruption in Darkshore already, but I have yet to find any widespread signs. I think it would be logical if the investigation continued with the furbolgs. Would you find one of their camps, and return to me if you see any signs of corruption?", sourceObjective = "Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine.", progress = "How goes your search, {name}?", completion = "This is terrible news indeed, {name}.\n\nWith the furbolgs this close to Auberdine, we will have to prepare ourselves for the inevitable.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[985] = { id = 985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Big a Threat?", description = "You've already proven adept at scouting our enemy, {name}. Do you have what it takes to fight them as well?\n\nNot all adventurers prefer straightforward combat to the art of stealth and evasion.\n\nIf you think you're up for the task, then the furbolg camp south of Auberdine is currently the biggest threat to our people. You'll find some of the Blackwood tribe there. Kill 8 pathfinders and 5 windtalkers, and return to me here.", sourceObjective = "Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine.", completion = "Wash the blood from your garments, {name}, and do not mourn what you had to do. Instead, give thanks. You have lessened the threat to our people here in Auberdine, even if Darkshore is still in jeopardy from the effects of fel moss.", sourceObjectiveStatus = "unverified-source-field" }
quests[986] = { id = 986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Master", description = "{name}, your skills have already helped me in my endeavor. Could I impose on you again to help Grimclaw and his master Volcor? In addition, I can craft you a magical cloak that will allow you to walk unhindered by Darkshore's creatures while you look for him.\n\nTo create the cloak, I'll need five fine moonstalker pelts from a moonstalker sire or matriarch to have enough material. The cats can be found near Wildbend River to the south, or even farther south near Ashenvale.", sourceObjective = "Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine.", progress = "I can't in good conscience permit you to seek Volcor until I've crafted that cloak for you.", completion = "These will do nicely, {name}. I shall set to work on the cloak immediately.\n\nGive me a few moments, then return to me.\n\nOh, one more thing: after you've used the enchantment on the cloak you'll be limited in your interactions with others. If you can help it, do no more than speak to others. Much more than that could dispel the illusion.", sourceObjectiveStatus = "unverified-source-field" }
quests[990] = { id = 990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trek to Ashenvale", description = "{name}, my mistress, Raene Wolfrunner, awaits you in the city of Astranaar within Ashenvale. With your help, perhaps we can at least ease some of the corruption that's taken hold there.\n\nHead south from here and stay close to the road--you'll find your way there without issue if you follow those directions.", sourceObjective = "Find Raene Wolfrunner in Ashenvale.", completion = "Ah, a {class} from Darkshore. Selarin has done well to send you here so quickly, {name}. I wish your trip here wasn't under such dire stress. Perhaps with your help we can improve matters.\n\nI would start my visit by speaking to the other citizens of Astranaar. Some could surely use your aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[991] = { id = 991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "{name}, a longtime friend of mine is also aiding the Sentinels here in Ashenvale, but he has yet to return.\n\nHe had leads on finding an item that he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left here, he mentioned seeking out a gem for the rod.\n\nHe mentioned the gem possibly being hidden at the shrine in Lake Falathim at the base of the mountain to the west. The gem was being held there before it was overrun.\n\nFind my friend, {name}, please.", sourceObjective = "Find Teronis in Ashenvale.", completion = "Teronis' body lies broken atop the island. For some unknown reason, the murlocs have left it alone.\n\nThe deep slashes across his corpse obviously came from the weapons and claws of the murlocs.", sourceObjectiveStatus = "unverified-source-field" }
quests[992] = { id = 992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gadgetzan Water Survey", description = "We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested!\n\nWith the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first.\n\nTake this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!", sourceObjective = "Use the untapped dowsing widget near the pool of water by Sandsorrow Watch. Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.", progress = "Welcome back, Junior Surveyor {name}!  Have you completed your assignment yet?", completion = "What's this?  You were ambushed by some sort of bad mojo creepy-crawly?  Oh, this does not bode well for the Gadgetzan Water Company, no indeed...\n\nI guess I should have told you about the reports coming in on some crazy bug-creatures that appear to be sucking up all the water in the desert.  At first, I thought it was just a crock.  We have enough trouble with the nomads as is; I thought it was just more of their shenanigans.  Well, now we know at least!", sourceObjectiveStatus = "unverified-source-field" }
quests[993] = { id = 993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lost Master", description = "The cloak is complete, {name}. The time has come to find Volcor. I can only hope we are in time.\n\nThe cloak's magic, once invoked, will not last long; perhaps five minutes. It will be up to you to know when to use it: I would suggest waiting until you find Grimclaw.\n\nIf what he has told me is true, you will find his master in a cave south of here. Grimclaw will be alongside the road waiting for you. Signal to him by waving when you see him, and he'll point the way towards his master.", sourceObjective = "Find Volcor in Darkshore and give him the Enchanted Moonstalker Cloak.", completion = "Wonderful! Terenthis found someone to help me.\n\nAnd look, a moonstalker cloak...<cough> Oh... that hurts. Thank you, {name}.\n\nThe furbolgs wounded me before I managed to evade them. Give me a moment, and I should be fine to talk some more.", sourceObjectiveStatus = "unverified-source-field" }
quests[994] = { id = 994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape Through Force", description = "All right, {name}, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there. Once there, we can part ways.\n\nTerenthis will want to hear your version of the story immediately, so head to Auberdine after we make it out of here.", sourceObjective = "Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.", completion = "{name}! I'm pleased to see you've returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond.", sourceObjectiveStatus = "unverified-source-field" }
quests[995] = { id = 995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape Through Stealth", description = "All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready.\n\nRemember, after you've escaped, meet Terenthis back in Auberdine. I'll head there on my own since I'll probably be moving faster than you.", sourceObjective = "Escape the Furbolg cave and meet Terenthis in Auberdine.", completion = "{name}! I'm pleased to see you've returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond.", sourceObjectiveStatus = "unverified-source-field" }
quests[996] = { id = 996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[997] = { id = 997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denalan's Earth", description = "Are you heading to the south?  To Lake Al'Ameth?  If so, then I have a task I might ask of you...\n\nMy colleague Denalan has a camp along the eastern end of the lake, where he is studying and experimenting on the plant life of Teldrassil.  He requested a package of rare earths from Darnassus and it was late, only recently arriving here in Dolanaar.\n\nCan you take the package to him?", sourceObjective = "Bring the package of Rare Earth to Denalan at Lake Al'Ameth.", progress = "You have something for me?", completion = "Ah, it's here!  I have waited for this rare earth for quite some time.  I hope it's still fresh...\n\nThank you for bringing it to me, {name}.  You are a {race} who is generous with his time.", sourceObjectiveStatus = "unverified-source-field" }
quests[998] = { id = 998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[999] = { id = 999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Dreams Turn to Nightmares" }
quests[1000] = { id = 1000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", sourceObjective = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "Greetings, {class}.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well.", sourceObjectiveStatus = "unverified-source-field" }
quests[1001] = { id = 1001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzbox 411", description = "A tiny voice crackles from deep within the machine.\n\n\"Wizbang here! The next Buzzbox is north of Auberdine, on the beach\n\nSo, that Buzzbox is number 411 and it needs 3 Thresher Eyes for its repairs. They're just off the coast! The darkshore threshers... *Hic*... Sorry about that...\n\nJust like last time, when you give the Buzzbox the goods, it'll spit out your reward. *Hic*... What? No, I'm fine!\"", sourceObjective = "Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411.", progress = "The machine's hatch is open and it seems to wait expectantly for 3 Thresher Eyes to be placed inside.", completion = "The Buzzbox hums to life soon after you place the Thresher Eyes inside. There is a moment of static before you hear a familiar tiny voice call out.\n\n\"Crawler wine is the best...\" *hic*\n\n\"What? Oh, you fixed it already? Wow, you're a fasht one. Sho, would ya like to fix another?\"\n\nYou believe you hear a liquid being poured into a cup, followed by loud gulping sounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[1002] = { id = 1002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzbox 323", description = "The Buzzbox gives a burst of static as you hear Wizbang begin to speak.\n\n\"The next Buzzbox is number 323. Ish north of Auberdine but... where's the ale? Wha? Oh, ish on the road sho ya shouldn't have trouble finding it near the bridge.\"\n\nWizbang mumbles something incoherent before you hear a loud gulping sound.\n\n\"Thish one needs Moonstalker Fangs... 6 of 'em.\"", sourceObjective = "Collect 6 Moonstalker Fangs and place them in Buzzbox 323.", progress = "Though you have yet to place the 6 Moonstalker Fangs inside, you believe you hear the sounds of static and incoherent gnome ramblings coming from within. Could someone else have fixed the machine already?", completion = "The Buzzbox suddenly leaps into action, and you can hear the distinct sounds of teeth being ground to dust coming from within.\n\n\"Sho, ya made it! Thatsh exshellent newsh... Sho... Why doncha move along? Oh! Unless you want another job!\"", sourceObjectiveStatus = "unverified-source-field" }
quests[1003] = { id = 1003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzzbox 525", description = "Over the boiling noises and dripping sounds coming from the machine, you hear Wizbang's wavering voice call out.\n\n\"Nexsht onesh far south down the road. Shouldn't be hard to find... jusht off to the shide... near a fensh. I think I hid it in shum bushesh... Bushessh. Hehehe... Yesh, Buzzbox 525 takes grizzled scalps from thoshe grizzled thistle bears. Boy thash a mouthful. Grizzshled... Hehehe...\"\n\nYou hear more gulping sounds as the machine cuts out. Then, suddenly, it bursts back to life.\n\n\"4!\"", sourceObjective = "Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525.", progress = "You hear singing coming from Buzzbox 525.\n\n\"Though crawler wine's shweet, and thresher ale fine, and moonstalker moonshine ish grand. There's nothing sho dear, as a thistle bear beer, and shoon I shall have shome on hand!\"\n\nThe hatch is open and awaits the 4 grizzled scalps as you hear the song repeated over and over.", completion = "\"Sho yash gotsh the scalps in? That'sh sho great... Wha? Well, yesh I shuppose ya have realized that I can speaksh to ya without the materials in the machine. But I was telling the truth when I shaid they were broken!\n\nSee, in addition to being communimacation toolsh, the Buzzboxes also brew and distill fine liquor. Shorry for any deceptshion, but the nightelves do not apprecimerate my liquor trade in their townsh. I put shomething special in thish box to show my gratitude for yer effortsh. Enjoy!\"", sourceObjectiveStatus = "unverified-source-field" }
quests[1004] = { id = 1004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", sourceObjective = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "Greetings, {class}.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well.", sourceObjectiveStatus = "unverified-source-field" }
quests[1005] = { id = 1005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lurks Beyond" }
quests[1006] = { id = 1006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lies Beyond" }
quests[1007] = { id = 1007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Statuette", description = "I would charge you with a task, {name}.\n\nI was on my small vessel, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws!  I fled, carrying what supplies I could to make this meager camp.\n\nBut when I reached the shore and ran... my prized possession was lost.\n\nPlease, {name}, find the site of my ambush, along the coast to the north, and search for an ancient statuette.  It is the reason I have braved the dangers of the Zoram Strand.", sourceObjective = "Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand.", progress = "Have you found the statuette, {name}?", completion = "You found it!  Thank you, {name}!\n\nThe old city of Zoram holds many secrets, and this statuette may be the key to many of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[1008] = { id = 1008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zoram Strand", description = "There is evil lurking on our northwestern coast, known as the Zoram Strand.\n\nIt is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas.  It has been lost to the night elves for ages.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must slay these fiends and throw them back to the depths!\n\nReturn to me when your mission is complete.", sourceObjective = "Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar.", progress = "We cannot allow the naga to invade our coasts, {name}.  It is vital that you go to the Zoram Strand and complete your mission.", completion = "Very well done, {name}.  Your actions in the Zoram Strand against the naga are commendable.\n\nI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves.  We know this, for we share a history with them.\n\nIt is a history I care not to repeat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1009] = { id = 1009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuzel", description = "I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock.\n\nThat key is a ring, the Ring of Zoram.  It belonged to the rulers of this city before the waves of the Sundering drowned it.\n\nFor years the ring was lost, but the naga have recently found it.\n\nTheir leader, Ruuzel, dwells on an isle on the northern edge of Zoram.  Please, {name}, retrieve the ring for me!", sourceObjective = "Bring the Ring of Zoram to Talen near the Zoram Strand.", progress = "It is said that the Ring of Zoram is the key to any lock within the city.  Do you have it, {name}?", completion = "You found the ring!  Thank you, {name}.  Please take this as payment, and know that your deeds today will remain forever in my memory.", sourceObjectiveStatus = "unverified-source-field" }
quests[1010] = { id = 1010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bathran's Hair", description = "There is a plant that once grew in the old ruins of Bathran's Haunt to the north.  The plant was called Bathran's Hair and was known to cure ailments of the spirit.\n\nThere is a sick child in the village, and I believe it is more than just a physical illness.  Will you go to Bathran's Haunt and search it for Bathran's Hair?  I may need it to properly treat the child.\n\nBathran's Haunt lies north of Maestra's Post and just south of the border to Darkshore.", sourceObjective = "Bring 5 Bathran's Hair to Orendil Broadleaf in Ashenvale.", progress = "Have you gathered the Bathran's Hair, {name}?  The child's health grows weaker by the hour...", completion = "Ah, you have the hair!  Now I will mix a cure for the child, and pray my concoction works.\n\nAnd... Forsaken are at Bathran's Haunt?  Very troubling to hear, that is.  Very troubling indeed...", sourceObjectiveStatus = "unverified-source-field" }
quests[1011] = { id = 1011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forsaken Diseases", description = "The Forsaken, the undead arm of the Horde, have crept into Ashenvale, lurking at our ruins and our barrows.  We believe their goal is to spread disease amongst the lands of the night elves.  We must confirm this!\n\nThe Forsaken have a camp south of here, near the Dor'Danil Barrow Den, where they create poisons and diseases and place them in bottles.  Fight your way into that camp and steal a bottle of disease.  Return with such a bottle.  I will test it and find its purpose.", sourceObjective = "Bring a Bottle of Disease to Kayneth Stillwind in Forest Song.", progress = "Did you find the camp, {name}?  Do you have a bottle of disease?", completion = "Very good, {name}.  Now... by testing the contents of this bottle, the goals of the Forsaken will be revealed!", sourceObjectiveStatus = "unverified-source-field" }
quests[1012] = { id = 1012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insane Druids", description = "When I struggled with the Forsaken's poisons, I had a vision.  I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!  They are now errant ghosts, severed from their bodies and driven mad.\n\nSo that the druids' spirits might some day find peace, you must enter the Dor'danil Barrow Den and destroy its once great leaders: Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak.\n\nDo this, then return to me.", sourceObjective = "Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.", progress = "The anguish of the Dor'danil druids still haunt my dreams, {name}.  You must destroy their leaders!", completion = "I felt the anguish of the Dor'danil Barrows lessen, and knew you had completed your task.\n\nIt was grim work you did, {name}, for the spirits you destroyed were merely victims of the Forsaken's evil.  But with their destruction, let us hope the other maddened spirits find peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[1013] = { id = 1013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of Ur", description = "{name}, Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection.  Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to ... certain parties among the Forsaken.\n\nEnter Shadowfang Keep and find the book.  Bring it to me, and I will report your service to our Dark Lady...", sourceObjective = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.", progress = "Did you find the book, {name}?", completion = "Very good.  This book will add nicely to my collections of the workings of Ur.  His knowledge was great, but his conscience held him from true power.  And so when the Scourge came and his strength was tested, it failed.\n\nWe of the Forsaken cannot afford such weakness, if we are to survive...\n\n...If we are to conquer.", sourceObjectiveStatus = "unverified-source-field" }
quests[1014] = { id = 1014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arugal Must Die", description = "Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain.\n\nI shall see to it that his magic is eradicated, {name}. But I leave it in your hands to see that Arugal meets the death he so deserves.\n\nTravel to Shadowfang Keep and put an end to Arugal's foul spells once and for all. Bring to me the vile wizard's head!", sourceObjective = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.", progress = "With Arugal's death we stand to increase the Dark Lady's stronghold on Lordaeron.", completion = "Silverpine Forest is finally free from the vice of that wretch Arugal. You have done the Dark Lady a great service, {name}. Your tenacity shall be rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[1015] = { id = 1015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", sourceObjective = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "What makes you think I wish to be pestered by the likes of you, {class}?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?", sourceObjectiveStatus = "unverified-source-field" }
quests[1016] = { id = 1016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Bracers", description = "Take this divining scroll--it can determine the creator of these elementals. But you will need something from them to use as a reagent to focus scroll's magic--their bracers should do nicely.\n\nA few intact bracers from the creatures should be enough. The other bracers will be useless for our purposes, but they may be worth something to a merchant if you wish to sell them. Once you have the intact bracers attempt to use the scroll. Return to me with the results and we shall proceed from there.", sourceObjective = "Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge.", progress = "Since you must destroy the bracers to kill the elementals, it will probably be difficult to find the specific ones that contain the information the divining scroll needs. You can trade bracers with others in order to obtain the ones you need, or perhaps you have the divined paper already?", completion = "Well done, {name}, this should give us the information we need to have the culprit discovered. How would you feel about taking out the mage who fills our pools with corrupt elementals? The corruption of Ashenvale and beyond makes my stomach turn on its own--to have a wizard actively attempting to destroy it further sickens me to no end. We shall make him pay.", sourceObjectiveStatus = "unverified-source-field" }
quests[1017] = { id = 1017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Summoner", description = "There's only one undead mage in the Barrens capable of defiling this many water elementals. He's also the only one foolish enough to try. Sarilus Foulborne is probably sitting at the top of Dreadmist Peak, laughing at me.\n\n{name}, you must go into enemy territory and destroy this miscreant. I have had enough of his idiocy and we must show him what happens to those who annoy the Sentinels.\n\nDestroy him and bring me his head. Be wary though, the Horde may be watching for you.", sourceObjective = "Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.", progress = "Is it done? Is Sarilus Foulborne dead?", completion = "Now I can see that repugnant smile wiped from his face forever. You have done very well, {name}. Take this, the Light of Elune, drink of it when all seems lost and death is near. It may save you, Goddess willing.", sourceObjectiveStatus = "unverified-source-field" }
quests[1018] = { id = 1018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", sourceObjective = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "Greetings, {class}.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well.", sourceObjectiveStatus = "unverified-source-field" }
quests[1019] = { id = 1019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", sourceObjective = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "What makes you think I wish to be pestered by the likes of you, {class}?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?", sourceObjectiveStatus = "unverified-source-field" }
quests[1020] = { id = 1020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orendil's Cure", description = "{name}, I have created a cure that I believe will help the afflicted child.  Take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.\n\nTo reach Astranaar, follow the road south, then east.", sourceObjective = "Bring Orendil's Cure to Pelturas Whitemoon in Astranaar.", progress = "I must apologize, for I have no time to speak.  My child, Relara, is deathly ill!", completion = "This is from Orendil?\n\nHis skill with herbs and healing is great.  This cure gives me hope, when before I had little...", sourceObjectiveStatus = "unverified-source-field" }
quests[1021] = { id = 1021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Satyr! Dryads in Danger!", description = "Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n{name}, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.", sourceObjective = "Find Anilia in Xavian in Ashenvale.", completion = "Judging by the gaping wound in her side, Anilia is on the verge of death.", sourceObjectiveStatus = "unverified-source-field" }
quests[1022] = { id = 1022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Howling Vale", description = "Though we have put many resources and much effort into driving the remaining demons from the Felwood to the north, our successes have been few. We have been able to keep much of the demonic presence from Ashenvale.\n\nTo the north, near the Felwood border, the ruined shrine of Mel'Thandris has been overtaken by mysterious wolf-men. Their chilling calls have led the area to be known as the Howling Vale. The Tome of Mel'Thandris kept at the shrine may shed some light on why these wolf-men have come.", sourceObjective = "Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.", progress = "The tome of the shrine is a mysterious object. It is not a book in the traditional sense. The leaves of the tome were blessed by Mel'Thandris herself, and records events of import in its pages.\n\nIt is hard for me to explain. If you go to the shrine, you will understand.", completion = "The Tome of Mel'Thandris works in strange ways. The events it records, the events it shows... No one truly understands why it does what it does.\n\nNonetheless, it is clear that what Priestess Starsong received--this Scythe of Elune--bears further investigation.", sourceObjectiveStatus = "unverified-source-field" }
quests[1023] = { id = 1023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "As you rummage through Teronis' belongings, you find a journal that is still in good condition.\n\nYou take the journal and leave Teronis' corpse as is.\n\nThe only thing left to do is find the gem Teronis was seeking. Raene mentioned it being in the area. Perhaps the murlocs have it...", sourceObjective = "Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal.", progress = "Ah, welcome back, {name}.", completion = "This is terrible, {name}. Teronis is dead?!\n\nThe time for mourning will come, but for now we must focus our efforts. I shall send some of the Sentinels to recover Teronis' body as soon as possible.\n\nYou have Teronis' journal and the gem he was seeking. Do you think you're capable of completing his task? I would rest much better knowing his death was not in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[1024] = { id = 1024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "You'll have to do the research yourself, but from what notes Teronis has made, it sounds like your next course of action is to find the other pieces of the rod Dartol created. I would start by heading to the moonwell east of Iris Lake. When you're ready, follow the road and turn north when you reach a small sitting area on your left.\n\nA dryad there named Shael'dryn is better suited to guide you. Seek her out.\n\nKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.", sourceObjective = "Find Shael'dryn at the moonwell to the northeast.", progress = "Hello. How are you?", completion = "Oh, Raene sent you? It must be serious indeed. What can I help you with?", sourceObjectiveStatus = "unverified-source-field" }
quests[1025] = { id = 1025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Aggressive Defense", description = "Before you travel to the moonwell I have another task that will aid the people of Ashenvale if you would like to test your skills.\n\nAlong the road heading east before the Falfarren River, furbolgs have been attacking travelers. Their tortured minds feeding upon fear, and their appetites satiated by the blood of innocents.\n\nAid the Sentinels in protecting the lands by showing those monsters the same mercy they have shown our kind.\n\nI believe their camps are south of the road... be careful.", sourceObjective = "Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.", completion = "You have done well, {name}. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[1026] = { id = 1026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "I wish your tidings were better.\n\nRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.\n\nIf your goal is to find the next piece of the rod, then you'll have to find the key to open the chest it's in.\n\nThe wooden key is on one of the treants northeast of here, near Felwood. Once you have it, look for a small glade west of the road near the Felwood border... the chest should be hidden around there.", sourceObjective = "Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell.", progress = "It upsets me so that the treants have become corrupt. I wish I could do more to help them.", completion = "I'm pleased to see you're back, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1027] = { id = 1027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "The final piece of the rod was given to the druids of Dor'danil for safekeeping. I have no idea where they hid it. I'm sorry I can't help you more than that.\n\nAll I can tell you is to follow the road that leads towards the Barrens. The druids took shelter to the east of that road, but they won't be of much help to you: they were killed recently... it's something I don't like to think about much.\n\nWhen you find the final piece, bring it to me and I will help you reconstruct the rod.", sourceObjective = "Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.", progress = "Did you find the final piece of the rod, {name}?", completion = "You found the final piece? Wonderful for you... and for Raene.\n\nI guess we'll have to see about repairing it, won't we?", sourceObjectiveStatus = "unverified-source-field" }
quests[1028] = { id = 1028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "Here is the completed rod, {name}. Reconstructing it was simple... it's finding the shrine that has the power to recharge it that will be the hard part.\n\nWith some focus and effort it shouldn't be too hard for someone like you, who's already accomplished so much.\n\nHead southeast of here--there are very few paths, so be careful--and keep your eyes to the north. The shrine is hidden within the mountains that surround this glade.\n\nOnce there, place the rod within the shrine... the rest is magic. Hehe.", sourceObjective = "Find the hidden shrine and re-enchant Dartol's Rod.", progress = "You can sense a subtle yet powerful force within the shrine and surrounding trees.\n\nYou begin placing the rod within the shrine and a soft thrumming noise emits from around you as the shrine begins to glow...", completion = "After the glow dies, you can see the re-enchanted rod within the shrine's basin.", sourceObjectiveStatus = "unverified-source-field" }
quests[1029] = { id = 1029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.\n\nGood luck, {name}.", sourceObjective = "Return to Raene Wolfrunner in Astranaar.\n\nProvided item:", completion = "You've recreated the rod Teronis had set out to find? That's wonderful to hear.\n\nTeronis would be proud to see his quest is continuing even after his tragic passing.", sourceObjectiveStatus = "unverified-source-field" }
quests[1030] = { id = 1030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "Alas, I'm not completely certain what he had in mind next.\n\nIf what he said was true about the rod's power, then it will allow you to take on another form altogether. Which form, I do not know.\n\nPerhaps he meant to use its powers to get closer to the tainted furbolgs, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was safe from the effects of Fel Moss.\n\nI would start your search southeast of Mystral Lake.", sourceObjective = "Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him.\n\nProvided item:", completion = "Yes, yes... you are one of my kind, but still whole. Still clean.\n\nI am unsure how you have escaped the atrocities the night elves have visited upon our people, but I am glad to know that I am no longer alone.\n\nCorruption now runs through the veins of our kin, young one, corruption brought down upon us by the prideful night elves. They are the ones who did this to our people... They are the ones I blame for being cast out of my tribe.\n\nAt night I can still see the campfires burning in the darkness.", sourceObjectiveStatus = "unverified-source-field" }
quests[1031] = { id = 1031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Branch of Cenarius", description = "Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.", sourceObjective = "Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song.", progress = "Have you found them? What did Anilia say? Where is she?", completion = "Anilia died? No... that can't be! It was just yesterday that we were running and playing together in the woods.\n\nI guess those days are over...", sourceObjectiveStatus = "unverified-source-field" }
quests[1032] = { id = 1032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyr Slaying!", description = "I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.\n\nI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.", sourceObjective = "Bring 16 Satyr Horns to Illiyana in Forest Song.", progress = "Please, help me avenge Anilia's death.", completion = "Thank you, kind {race}. My sister's spirit is gladdened by your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[1033] = { id = 1033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Tear", description = "I had hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through my child.  We must find more powerful medicine!  Thankfully, Orendil spoke to me of further remedies to try should his first one fail.\n\nElune's Tear is a type of stone that rests in only one place: the isle on Iris Lake, east of Astranaar.  Orendil said the stone will wash away corruption... please, {name}, bring me Elune's Tear and pray it will end my child's sickness!", sourceObjective = "Bring Elune's Tear to Pelturas in Astranaar.", progress = "{name}, did you find Iris Lake?  Do you have the Tear?", completion = "Oh, you found it!  I will place the tear in a stew, and pray that it will cure her.\n\nThank you!  Thank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[1034] = { id = 1034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Stardust", description = "Elune's Tear washed clear some of my daughter's sickness.  Her nightmares are lessened and I thank the goddess for her blessing.  But ... fever still rages within her.\n\nOrendil told me of a frosted dust found among the Ruins of Stardust.  Perhaps it will abate Relara's fever.  Gather some of the dust, then please return to me.\n\nThe Ruins of Stardust lie to the south, {name}.  May Elune speed your journey.", sourceObjective = "Bring 5 Handfuls of Stardust to Pelturas in Astranaar.", progress = "Do you yet have the Stardust, {name}?", completion = "You gathered the dust!  I will create a poultice from these -- it should bring down Relara's fever.\n\nThank you again, {name}.  Without your help, my child would surely perish.", sourceObjectiveStatus = "unverified-source-field" }
quests[1035] = { id = 1035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Sky Lake", description = "Relara's fever has passed, but she is still very weak.  I do not believe time alone will give her back the strength she has lost.  I believe it will take the power of a moonstone.\n\nWe used to gather moonstones at Fallen Sky Lake to the southeast... until the Shadethickets came.\n\nTheir leader, a Shadethicket Oracle, gathered up all the fallen moonstones and hoards them.  Now, you must retrieve a moonstone from the Oracle.\n\nAnd to do that, I fear that you must slay him.", sourceObjective = "Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.", progress = "Did you face the Shadethicket Oracle, {name}?  If so, then please hand me the fallen moonstone.  Relara has strength left for only a few more breaths!", completion = "Oh, {name}, you have saved my daughter!  I know the power of the moonstone will give back my daughter her strength!\n\nI can never repay you fully for the aid you have given me, but... please, take this.  Other than Relara, it is my most dear possession.", sourceObjectiveStatus = "unverified-source-field" }
quests[1036] = { id = 1036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avast Ye, Scallywag", description = "{name}... yeah, I've heard of you.  I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers.  Fleet Master Firallon is looking for hale and hearty <men/women> just like you for a special mission.\n\nIf you're interested, head on out to the Crimson Veil and speak with him below decks.  She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.", sourceObjective = "Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.", completion = "Avast ye, scallywag.  I hears that ye be the type for a bit o' the skullduggery.  Well, if yer no friend of Booty Bay, then ye might have a special place with the Bloodsail Buccaneers.\n\nArrrrr...", sourceObjectiveStatus = "unverified-source-field" }
quests[1037] = { id = 1037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velinde Starsong", description = "Velinde Starsong was my predecessor here in Ashenvale Forest. At first it seemed she had the situation in Felwood under control, but little by little her efforts faltered. One day, she simply disappeared.\n\nI was sent here to continue her work. I'm afraid I know nothing of the priestess, however. Perhaps Thyn'tel Bladeweaver, one of the commanders of the Sentinels, knows further details of her disappearance that I was not a party to.\n\nSurely she will understand the import of such information.", sourceObjective = "Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.", completion = "Velinde Starsong? That the priestess disappeared some time ago is almost certainly common knowledge. As to further details about the events that surrounded her departure... it would take good reason for me to divulge such information.", sourceObjectiveStatus = "unverified-source-field" }
quests[1038] = { id = 1038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velinde's Effects", description = "The Tome of Mel'Thandris showed you this? I suppose there would be little harm in allowing you to examine her belongings. This key will allow you to open the chest where we stored her things in the Sentinels' bunkhouse. She kept a journal of her duties, if there is anything to be learned, it will be from that.\n\nI should tell you, the Sentinels believe that she had her own reasons for leaving, and expect that she could return at any time. The priestess has done much in the past to earn our trust.", sourceObjective = "Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.", progress = "What'd you find out?", completion = "It seems that Velinde's disappearance is more troubling than it originally appeared. Even still, I cannot believe that she has come to a bad end. Perhaps it would be beneficial for us to make contact with her.\n\n{name}, since you have shown a vested interest in this matter, I would like to enlist your aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[1039] = { id = 1039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Barrens Port", description = "Ratchet is the only port in the Barrens. Most likely Velinde found a trading vessel in Ratchet to take her to Blackwater Cove in Azeroth. We've had limited dealings with the goblins that run the port, but the master of the dock should have information about the comings and goings of ship passengers.\n\nFollow the road southeast through Ashenvale and you will find yourself in the Barrens. Watch your step, {name}, warriors of the Horde patrol the land. You will be safe at the port, though.", sourceObjective = "Speak with Wharfmaster Dizzywig at Ratchet in the Barrens.", completion = "{race}, eh? Must admit, we don't get much of your type out here. Looking for someone, eh? Just give me a moment, I'm sure I have it written in one of my ledgers.\n\nLot of people travel through here, though, so just give me a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[1040] = { id = 1040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Passage to Booty Bay", description = "Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see.\n\nVelinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely.\n\nNot much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him.\n\nMove along, now. I haven't all day for you.", sourceObjective = "Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.", completion = "Yes? Now, it doesn't look to me like you're the sort with goods that need shipping, so either you're looking for a job with my caravan--and there's no jobs to be had now--or you're probably talking to the wrong goblin.\n\nSo which one is it?", sourceObjectiveStatus = "unverified-source-field" }
quests[1041] = { id = 1041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Caravan Road", description = "Turns out I was wrong about you, and that isn't something that happens everyday.\n\nIt just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own.\n\nWe split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful.\n\nBe careful in the jungle, it is a deadly place even at the best of times.", sourceObjective = "Speak with Clerk Daltry in Darkshire.", completion = "With all the strange happenings of the last few years, I keep as good records of strangers as I can. Never know when it might come in handy... though it's usually not pleasant business when it does. Not to suggest anything about this Velinde you're looking for.", sourceObjectiveStatus = "unverified-source-field" }
quests[1042] = { id = 1042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Carevin Family", description = "No, I don't have any records of a Velinde Starsong staying in Darkshire... though, if you don't mind me saying, I can hardly imagine a night elf priestess taking a room in the inn, if you get my meaning?\n\nThese wolf-men you mentioned though, that's something I've heard about. Just the other day, Calor came into town with a string of their heads. He works with the Carevin family. Hunters of demons, undead, and other monstrosities. Speak with Jonathan, he's the head of the household.", sourceObjective = "Speak with Jonathan Carevin in Darkshire.", completion = "Dark times these are. Ill news is whispered from every swaying branch, and evil can be found under every rock.\n\nAnd in such times an unknown stranger enters my home and asks of worgen... I'll ask no forgiveness for my suspicions, only answers.\n\nAnd answers, I will have.", sourceObjectiveStatus = "unverified-source-field" }
quests[1043] = { id = 1043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scythe of Elune", description = "Your story rings true... I do not entirely understand your motives, but if your business here in Duskwood involves ridding the forest of worgen in any number, then I can forgo understanding for results.\n\nThere is a mine to the south that has been overrun with worgen... They appeared out of nowhere, but from what we know, that is where they first were found.\n\nGo about your business, but I would ask that if you find anything of import, you share it with me. We will accept any aid in our war against evil.", sourceObjective = "Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.", progress = "The woods are perilous for the unprepared. Keep your weapons close at hand and your wits even closer, or your next journey into the haunted forest may be your last.", completion = "It is an interesting story you tell, {name}. Though the Carevin family's influence is not large enough that we might find the root of these troubles and finish them once and for all, we will do what we can to contain the worgens' numbers in Duskwood.\n\nAlready I have instructed Calor to make this his first priority.", sourceObjectiveStatus = "unverified-source-field" }
quests[1044] = { id = 1044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answered Questions", description = "We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, {name}, and the darkness knows no respite.\n\nI will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood.", sourceObjective = "Return to Thyn'tel Bladeweaver in Darnassus.", completion = "So this is the fate of Velinde, is it? The high priestess will be disappointed to hear of this, they were good friends before her disappearance. Still, the Scythe of Elune was surely granted to her as a boon by our goddess, and it is unsettling to me that it has fallen out of her servants' hands.\n\nAnother matter for another time, however. I owe you my thanks in no small amount for what you have accomplished.", sourceObjectiveStatus = "unverified-source-field" }
quests[1045] = { id = 1045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "The night elves are as old as time, but their arrogance destroys their very world. And now it destroys our lives too. But that can no longer be controlled...\n\nI blame the elves for much, but we are still responsible for our actions. Even beyond the corruption, we are capable of great evil.\n\nRan Bloodtooth is one such evil. Power hungry, lusting... the corruption has only made him stronger. My hatred for the elves burns, but I do not wish ill upon their children, so we must police our own.", sourceObjective = "Kill Ran Bloodtooth, 4 Bloodtooth Guards and collect Ran Bloodtooth's Skull. Return to Krolg near Lake Mystral should you succeed.", progress = "Have you slain Ran yet, my friend?\n\nEven the Night elves do not truly deserve his wrath. His hatred burns even brighter than my own, but his mind is no longer his own. He is a threat to all the natural creatures of this forest.", completion = "You have done well, my friend.\n\nThe forest is still tainted, but at least we know we have done a small part to return it to its former glory. If you wish to return to me again, I would enjoy the company of my own kind.\n\nBe well. Perhaps our tribes will meet again under less violent times.", sourceObjectiveStatus = "unverified-source-field" }
quests[1046] = { id = 1046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raene's Cleansing", description = "Return to your own tribe and let them know of your victory here.\n\nShow them your trophy, and bask in the glory...", sourceObjective = "Bring Ran Bloodtooth's Skull to Raene Wolfrunner in Astranaar.", progress = "The Sentinels do what they can here in Ashenvale, but it's thanks to humans like you that we have gained the ground we have.", completion = "So, this is the skull of the fiercest furbolg threat in Ashenvale?\n\nI am more than pleased with your abilities, {name}. The Sentinels cannot thank you enough. I hope we can rely on you again in the future to help our people.\n\nI shall put this skull and Dartol's Rod in a place of reverence for others to see.\n\nTeronis would be proud. Thank you again.", sourceObjectiveStatus = "unverified-source-field" }
quests[1047] = { id = 1047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", sourceObjective = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "What makes you think I wish to be pestered by the likes of you, {class}?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?", sourceObjectiveStatus = "unverified-source-field" }
quests[1048] = { id = 1048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Scarlet Monastery", description = "Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly.\n\nNo doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants.\n\nTravel to the Monastery, {class}, and lay waste to High Inquisitor Whitemane and her top lieutenants.", sourceObjective = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.", progress = "Perhaps I was not explicit in my orders, {class}. I want High Inquisitor Whitemane killed once and for all. And while you're at it, take out her top brass as well.\n\nKill that zealot, Scarlet Commander Mograine. Lay waste to Herod, the Scarlet Champion. And slaughter Houndmaster Loksey and his filthy mutts too.\n\nNow begone!", completion = "You have served the Dark Lady well, {class}. 'Twas no small task I asked of you.\n\nYour loyalty to the Forsaken has been noted. And your tenacity in combat will be remembered.", sourceObjectiveStatus = "unverified-source-field" }
quests[1049] = { id = 1049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compendium of the Fallen", description = "The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?\n\nThe Forsaken whom we have allied with have a history wrought with deceit. Too hasty was our pact. Perhaps Cairne would have been wise to heed the warnings from Orgrimmar.\n\nDeep within the Scarlet Monastery lies the Compendium of the Fallen, guarded by crazed human zealots. Their method is forged from insanity but their research might prove useful.", sourceObjective = "Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.", progress = "Cairne is a brave and noble leader and I would trust him with my own life. But it is others that I do not trust in this political climate.\n\nOnce I have a chance to gather all the knowledge available I can provide sound council to the Chieftain.\n\nHave you had a chance to travel to Tirisfal Glades? To the Scarlet Monastery? The Compendium of the Fallen is just one piece in this complicated puzzle...", completion = "The Compendium of the Fallen! I was beginning to wonder if the very book existed!\n\nYou have served the tauren of Thunder Bluff well, {name}. Your dedication shall not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1050] = { id = 1050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mythology of the Titans", description = "The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea.\n\nBut perhaps, by studying the past, we can know what to expect and be better prepared for the unknown.\n\nBefore dire troubles fell upon Lordaeron, there was a bastion of knowledge tucked away in the Tirisfal Glades. It is rumored that a book called Mythology of the Titans was housed in the library of the old Monastery.\n\nBring it to me and perhaps together we can unlock the secrets of the past!", sourceObjective = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.", progress = "The Monastery was a seminary for Paladins-in-training. Once a stronghold of the Light, it fell into the hands of the crazed zealots of the Scarlet Crusade.\n\nThe Crusade believed their goal a noble one: to purify the land of the undead plague. But insanity tainted their plight and now they stand enemies to all.\n\nBring Mythology of the Titans to me so I can study it and house it here in Ironforge.\n\nThe corrupt halls of the Monastery are no place for such a historical treasure.", completion = "You have rescued the sacred text!\n\nYour journey was long and acquiring the book was undoubtedly no easy task. But  the dwarves of Ironforge stand to benefit from your success.\n\nThank you, {name}, on behalf of the Explorers' League.", sourceObjectiveStatus = "unverified-source-field" }
